(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-paged-kv-moe"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-1\">一 · 一个被 TPOT 击穿的夜晚：问题从哪里来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-2\">二 · 它解决的是配额与碎片，不是算力与通信</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-3\">三 · 机制按数据流走一遍，代价落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-4\">四 · 三个失败模式，各自对应一条边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-5\">五 · 与相邻方案的边界：统一池，而非各自为政</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-6\">六 · 边界：它救的是“同池争抢”，不是“容量不足”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-7\">七 · 请求入场：按最大生成长度预留 page 数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-8\">八 · 池分配：非连续物理页与水位记账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-9\">九 · Attention gather：page table 间接寻址的 IO 形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-10\">十 · 专家热度统计与分层驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-11\">十一 · 水位越限：KV 换出与权重降级的优先级裁决</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-12\">十二 · 请求结束：page 归还与热度表异步收敛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-13\">十三 · 边界条件：配额不等式何时失效、page 粒度何时反噬、水位阈值何时震荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-14\">十四 · 配额不等式：把“争抢”写成一条可解的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-15\">十五 · 命中率公式：热度统计的可计算形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-16\">十六 · Page table gather：attention 侧的开销推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-17\">十七 · 水位阈值与震荡：把换出策略写成状态机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-18\">十八 · 预留与归还：page 生命周期的可实现路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-19\">十九 · 统一显存池的可行域：配额不等式、失效边界与拷贝代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-20\">二十 · 请求形态决定配额是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-21\">二十一 · 长度分布与 page 尺寸的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-22\">二十二 · 并发与批大小的动态区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-23\">二十三 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-24\">二十四 · 配方与 SLO 双指标的对应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-25\">二十五 · 负载配方与失效边界：这套共存方案在什么请求形态下才成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-26\">二十六 · 硬件档位与三级存储的分工边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-27\">二十七 · 并行拓扑：专家并行度与 page 池的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-28\">二十八 · 量化方案与 page 尺寸的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-29\">二十九 · KV 策略：预留、换出与归还的时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-30\">三十 · 调度参数：批大小、SLO 与配额的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-31\">三十一 · 一个可复现的配置流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-32\">三十二 · 配方失效的三种边界：路由突变、page 过小、水位抖动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-33\">三十三 · 先把“谁先崩”排成一张序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-34\">三十四 · 显存：配额是零和的，碎片消除只买回一次</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-35\">三十五 · 带宽：两条互相踩踏的通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-36\">三十六 · 通信：page 粒度改变了集合通信的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-37\">三十七 · 功耗：常驻集合的静态底噪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-38\">三十八 · 尾延迟：三条失败模式的共同出口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-39\">三十九 · 规模上去以后，先崩的是配额而不是容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-40\">四十 · 精度问题：page gather 与权重降级两处数值断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-41\">四十一 · OOM：配额不等式被击穿的三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-42\">四十二 · 批抖动与路由不均：热度表的滞后代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-43\">四十三 · 尾延迟尖刺：page 尺寸与换入换出的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-44\">四十四 · 监控体系：把水位、命中率、换出事件放在同一时间轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-45\">四十五 · 回滚：把配额与热度策略做成可切换的参数面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-46\">四十六 · 失效条件、诊断信号与回滚边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-47\">四十七 · 对照维度：把“争抢同一块 HBM”拆成三个可比较的轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-48\">四十八 · 决策表：按负载形态选族内算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-49\">四十九 · 适用条件的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-50\">五十 · 与专家并行、分离式部署的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-51\">五十一 · 选型后的参数落点与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-52\">五十二 · 一个可执行的判断序列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-paged-kv-moe-sec-53\">五十三 · 同族算法怎么选：三条路线的边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:552px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.7 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入时按最大生成长度预留 KV page 数，page 从统一显存池分…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">attention kernel 按 page table gather …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">专家权重按访问频次统计热度，热专家常驻 HBM，冷专家换出到 host 内…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">显存池水位超过阈值时触发 KV page 换出或专家权重降级，优先保 KV…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求结束后 KV page 归还池，专家权重热度表异步更新</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-paged-kv-moe-sec-1\">一 · 一个被 TPOT 击穿的夜晚：问题从哪里来</h3>\n<p>某在线 MoE 服务在夜间流量爬坡时出现了一次典型的雪崩：TTFT 尚在 SLO 之内，但 TPOT 从稳定区间突然抬升，随后大批请求被判超时。事后回放请求轨迹，根因不是算力打满，也不是网络抖动，而是显存。该实例的 HBM 里同时躺着两样东西：一是按并发峰值预留的专家权重，二是随并发线性增长的 KV cache。白天流量低、上下文短，两者相安无事；夜间长上下文请求比例上升，KV 按连续方式分配，外部碎片让新请求找不到足够大的连续区间，调度器只能降低并发或拒绝请求。与此同时，路由分布发生了偏移，一批原本判定为“冷”的专家突然被高频选中，而这些专家的权重早已被换出到 host 内存，host-device 拷贝被串行插入 decode 的关键路径，单 token 时延出现尖峰，TPOT SLO 被击穿。这个事故暴露的不是某个 kernel 慢，而是<strong>两类显存消费者共用同一块 HBM、却各自独立管理</strong>的结构性问题。</p>\n<p>本片段要界定的正是这套算法的适用边界：它解决什么、不解决什么。先把问题写清楚。MoE 服务的显存占用可以拆成两项：</p>\n<div class=\"formula\">$$\\text{HBM}_{\\text{used}}=\\underbrace{N_{\\text{page}}\\cdot 2\\,L\\,H\\,d}_{\\text{KV}}+\\underbrace{\\sum_{e\\in\\text{hot}}|W_e|}_{\\text{resident experts}},\\quad \\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>第一项随并发与上下文长度线性增长，第二项由常驻热专家集合的大小决定。两项之和一旦逼近 HBM 容量，系统就进入互相挤压的状态：KV 要更多 page 才能接纳新请求，专家权重却占着不放；反过来，为了压低 TPOT 而扩大常驻专家集合，KV 的可用 page 数就被压缩，长上下文请求首先被牺牲。连续分配的 KV 进一步恶化了这个局面——即使总空闲字节足够，外部碎片也会让大请求分配失败。这就是本算法要解决的具体推理问题：<strong>在 MoE 在线服务中，让专家权重与 KV cache 在同一块 HBM 上共存，且长上下文与高并发能够同时成立</strong>。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-2\">二 · 它解决的是配额与碎片，不是算力与通信</h3>\n<p>把适用范围说窄一点，比说宽更有用。这套算法的作用域是<strong>单机显存资源的管理层</strong>：它把 KV cache 切成固定大小的 page、按需分配、不要求物理连续；把专家权重按访问热度分层驻留，热专家常驻 HBM，冷专家放在 CPU 内存或 NVMe；两者放进同一个统一显存池，按 SLO 动态调整配额。核心配额关系是一条硬约束：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>其中 $\\mathcal{H}$ 为常驻热专家集合，$W_e$ 为单专家权重字节，$N_{\\text{page}}$ 为已分配 KV page 数，$S_{\\text{page}}$ 为单 page 字节。池水位超过阈值时，系统优先换出 KV page 或降级专家权重，以保住延迟 SLO。注意这条约束里没有出现算力项、没有出现互联带宽项、也没有出现路由策略项——这正是它的边界所在。</p>\n<p>它<strong>不解决</strong>以下问题：其一，不解决专家并行下的 All-to-All 通信开销，也不改变路由算法本身的选择分布，路由突变只能被观测和缓解，不能被消除；其二，不解决 MMA 吞吐或量化精度问题，NVFP4/FP8 的数值路径与本算法正交；其三，不解决跨节点显存聚合，它假设的是单机 HBM + host 内存 + NVMe 三级存储；其四，不解决容量因子路由导致的令牌丢弃，那属于另一条调度路径。工程上最常见的误用，是把它当成“显存不够就卸载”的万能开关——如果瓶颈在通信或算力，调 page 大小和热度阈值不会带来任何收益，只会增加地址计算开销。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-3\">三 · 机制按数据流走一遍，代价落在哪里</h3>\n<p>按请求生命周期看，机制分三段。第一段是准入：请求进入时按最大生成长度预留 KV page 数，page 从统一显存池分配，物理上不连续。这一步把“连续区间是否存在”从分配条件里删掉了，外部碎片因此消失，但代价是分配粒度变细、page table 变长。第二段是 attention：kernel 按 page table gather KV，FlashAttention 以 page 为粒度做 IO。地址计算从“基址 + 偏移”变成“查表 + gather”，page 越小，表越长、间接寻址占比越高，IO 效率下降。第三段是专家侧：按访问频次统计热度，热专家常驻 HBM，冷专家换出到 host 并按需预取；请求结束后 KV page 归还池，热度表异步更新，避免更新动作落在关键路径上。</p>\n<p>代价可以逐项对应到系统指标。显存方面，收益是利用率提升 20–40%，来源是碎片消除与冷专家移出；代价是 page table 本身占用显存，且预留按最大生成长度做，短请求会短暂占住用不到的 page。延迟方面，decode 阶段热专家命中率通常 &gt;90%，意味着绝大多数 token 不触发拷贝；但剩余部分一旦命中冷专家，host-device 拷贝串行插入关键路径，单 token 时延尖峰直接冲击 TPOT。带宽方面，page 粒度 IO 与专家预取共享 PCIe/NVMe 通道，两者在池水位告警时会同时活跃，形成带宽争抢。吞吐方面，page 过小会限制长上下文吞吐，此时即便显存利用率更高，端到端吞吐也可能低于连续分配方案——这是一个必须用标定实验确认的拐点，而不是可以假定的单调关系。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-4\">四 · 三个失败模式，各自对应一条边界</h3>\n<p>把失败模式当成边界的另一种写法，比罗列优点更能指导部署。第一，<strong>路由分布突变</strong>：请求集中到被换出的冷专家，拷贝串行插入 decode，TPOT 尖峰击穿 SLO。这条边界的含义是，热度统计必须是异步且带衰减的，冷热判定不能只看累计频次；同时换出策略要留出预取窗口，让拷贝与计算重叠，而不是等 miss 发生再搬。第二，<strong>page 尺寸标定过小</strong>：attention kernel 地址计算与 IO 效率下降，page table 间接寻址开销占比升高，长上下文请求吞吐反而低于连续分配。这条边界说明 page 大小是一个需要按上下文长度分布与 kernel 实现共同标定的参数，不是越小越灵活。第三，<strong>水位阈值设置不当</strong>：KV page 换出与专家权重降级频繁抖动，两者互相触发形成换入换出震荡，显存利用率提升被拷贝开销抵消。这条边界指向滞回设计——阈值需要死区，降级与恢复不能共用同一个水位点。</p>\n<p>一个具体的工程例子：某长上下文与高并发混合的在线服务，批大小随并发动态变化，SLO 以 TTFT 与 TPOT 双指标约束。若把 page 设为很小的固定值以追求碎片最小化，长上下文请求的 attention IO 会被切得过碎，吞吐下降；若把水位阈值设为单一硬阈值，流量爬坡时会出现 KV 换出与专家降级交替触发的震荡。正确做法是把 page 大小按上下文长度分档标定，把水位阈值做成带死区的双阈值，并让热度表更新与请求处理解耦。这些都不是算法本身的数学性质，而是部署时必须补齐的工程判断。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-5\">五 · 与相邻方案的边界：统一池，而非各自为政</h3>\n<p>与相邻算法对比，边界更清楚。相比连续分配的 KV cache，它用 page table 间接寻址消除外部碎片，代价是地址计算复杂化与小 page 的 IO 效率损失；它并不改变单请求的 attention 计算量，也不提升算力利用率。相比纯专家卸载方案，它把权重与 KV 放进统一显存池按 SLO 动态分配配额，而不是各自独立管理——这一点是关键差异：独立管理下，KV 扩容与专家常驻的决策互不知情，才会出现“总空闲足够但两边都喊不够”的局面。统一池把两者放在同一条约束 $M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$ 下，配额成为可调的量，而不是两个静态分区。</p>\n<p>适用规模的判断也由此得出：当专家权重常驻占用与 KV 峰值占用之和接近 HBM 容量、且请求形态是长上下文与高并发混合时，这套算法的收益最明显；当模型较小、专家权重可以全部常驻、KV 峰值远低于容量时，引入 page table 与热度统计只会增加复杂度而无收益；当瓶颈明确在跨节点通信或算力时，它不在关键路径上。材料给出的两个数字锚点——显存利用率提升 20–40%、decode 阶段热专家命中率通常 &gt;90%——应当被理解为该边界内的典型区间，而不是任何配置下的保证。</p>\n<p>最后落在一条可执行的判断上：部署前先测三个量——专家权重常驻占用、KV 峰值占用、以及路由分布的时间自相关性。前两者之和逼近 HBM 容量，说明配额冲突真实存在；第三者低，说明热度表需要更短的衰减窗口与更积极的预取，否则冷专家 miss 会直接变成 TPOT 尖峰。这三个量决定了这套算法是解药还是纯开销。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-6\">六 · 边界：它救的是“同池争抢”，不是“容量不足”</h3>\n<p>先把适用范围钉死：这套机制解决的是<strong>同一块 HBM 上两类增长源互相挤压</strong>——专家权重按模型规模常驻，KV cache 按并发与上下文长度线性增长，加上连续分配留下的外部碎片，使长上下文请求与高并发请求无法同时容纳。它不解决单卡 HBM 绝对容量不够、不解决跨机专家并行、也不解决权重本身太大而必须切分的问题。一次线上事故足以说明边界：某 MoE 在线服务在晚高峰把并发拉到高位，KV 连续分配后剩余 HBM 只剩零散空洞，此时一批长上下文请求到达，按最大生成长度预留的连续空间申请失败，调度器被迫拒绝或排队，TTFT 直接击穿 SLO；与此同时，路由分布偏移使请求集中到几个被判定为“冷”而换出到 host 的专家，host-device 拷贝串行插入 decode 关键路径，TPOT 出现尖峰。事故的根因不是算力不够，而是配额与碎片。</p>\n<p>配额关系必须显式成立，否则分页与分层只是把问题挪了个位置：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>其中 $\\mathcal{H}$ 为常驻热专家集合，$W_e$ 为单专家权重字节，$N_{\\text{page}}$ 为已分配 KV page 数，$S_{\\text{page}}$ 为单 page 字节。池水位越阈值时优先换出 KV page 或降级专家权重以保延迟 SLO——这条策略决定了它的失效方向：<strong>当 $\\mathcal{H}$ 的选取滞后于真实路由分布，或 $S_{\\text{page}}$ 标定过小，收益会被拷贝与寻址开销吃掉</strong>。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价落点</th><th>工程判断</th></tr></thead><tbody><tr><td>路由突变偏向已换出冷专家</td><td>host-device 拷贝插入 decode，单 token 时延尖峰</td><td>热度表异步更新必须快于路由漂移，冷专家预取要提前于首次命中</td></tr><tr><td>page 尺寸过小</td><td>page table 间接寻址占比升高，IO 效率下降，长上下文吞吐反低于连续分配</td><td>page 大小按 attention kernel 的 IO 粒度与地址计算开销折中，不能只按碎片率选</td></tr><tr><td>水位阈值设置不当</td><td>KV 换出与专家降级互相触发，形成换入换出震荡</td><td>阈值需带滞回，且两类动作分级而非同级竞争</td></tr></tbody></table>\n<p>代价还有一条常被忽略：page table 间接寻址让 attention kernel 的地址计算复杂化，FlashAttention 以 page 为粒度做 IO 时，小 page 意味着更多次 gather、更低的单次搬运效率，长上下文场景下这部分开销会直接抵消分页带来的碎片收益。因此它的适用边界是“长上下文与高并发混合、且专家热度分布相对稳定”的在线服务；材料给出的显存利用率提升 20–40%、decode 阶段热专家命中率 >90% 都建立在这个前提上。若路由本身高度不稳定、或上下文长度集中在极短区间，分页与分层的复杂度换不来对应收益，连续分配反而更省心。判断标准落在一条可观测指标上：单位 token 的 host-device 拷贝字节数与 page table 寻址开销占比，一旦逼近 KV 读取本身，这套方案就该退回或改配额策略，而不是继续调 page 尺寸。</p>\n<h3 id=\"alg-paged-kv-moe-sec-7\">七 · 请求入场：按最大生成长度预留 page 数</h3>\n<p>机制的第一步发生在请求被调度器接纳的瞬间，而不是第一个 token 被计算时。调度器读取请求的 <em>max_new_tokens</em> 与 prompt 长度，据此估算该请求在整个生命周期内可能触及的 KV 上限，并一次性向统一显存池申请对应数量的固定大小 page。这里的输入是请求元数据（prompt 长度、生成长度上限、采样参数），输出是一张属于该请求的 page table——一张逻辑页号到物理页号的映射表，物理页号由池分配器给出，彼此不要求连续。代价立刻体现：预留是保守的，按最大生成长度而非期望长度申请，因此池的瞬时占用高于真实需求，这是用显存换确定性——避免 decode 中途因分配失败而阻塞。</p>\n<p>预留量可写成 $N_{\\text{page}}^{\\text{req}}=\\lceil (L_{\\text{prompt}}+L_{\\text{max\\_new}})/P \\rceil$，其中 $P$ 为单 page 覆盖的 token 数。这个式子的工程含义是：$P$ 越小，外部碎片越少、内部碎片越多；$P$ 越大，page table 越短、gather 越粗，但尾部浪费越大。对长上下文请求，$L_{\\text{prompt}}$ 一项主导预留，池水位在入场阶段就被推高，这正是后续触发换出策略的根源。举例：一个 prompt 极长、生成很短的请求与一个 prompt 短、生成极长的请求，在同一 $P$ 下预留的 page 数可能相近，但前者几乎全部 page 在 prefill 阶段即被写满，后者则长时间处于“已预留未写入”状态，池的账面占用与真实带宽占用出现背离。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-8\">八 · 池分配：非连续物理页与水位记账</h3>\n<p>统一显存池是这套机制的中枢，它同时记账两类对象：KV page 与常驻专家权重。分配器维护空闲 page 链表与已分配水位，每次分配只返回物理页号，不承诺邻接。输入是上一步的 page 数请求，输出是物理页号列表与更新后的水位计数。代价在分配器的数据结构上：非连续分配意味着 page table 必须逐请求维护并随生成长度增长而追加条目，元数据本身占用显存，且 page table 的读写落在关键路径上。</p>\n<p>配额约束是这套设计的硬边界：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>其中 $\\mathcal{H}$ 为常驻热专家集合、$W_e$ 为单专家权重字节、$S_{\\text{page}}$ 为单 page 字节。这个不等式不是静态配置，而是每个调度周期都要复核的动态约束：当新请求入场推高 $N_{\\text{page}}$，不等式右侧膨胀，若逼近 $M_{\\text{HBM}}$，就必须收缩 $\\mathcal{H}$ 或拒绝/排队请求。工程判断在于：把不等式当作准入控制的第一道闸，比等到分配失败再回退要便宜得多，因为回退意味着已分配的 page 要被打回、已计算的 KV 要重算。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-9\">九 · Attention gather：page table 间接寻址的 IO 形态</h3>\n<p>decode 每一步，attention kernel 需要读到该请求历史所有 token 的 K/V。输入是当前 token 的 query、page table、以及池中散落的物理 page；输出是 attention 结果与更新后的当前 page 内容。FlashAttention 以 page 为粒度组织 IO：kernel 遍历 page table，对每个逻辑页取出物理页地址，把该页内的 K/V 块搬入片上存储参与分块计算。这一步的代价是双重的——地址计算复杂度上升，因为每个 page 的首地址都要经一次间接查表；IO 效率取决于 $P$，$P$ 过小时单次搬运的有效载荷不足以摊薄寻址与启动开销，长上下文请求的吞吐反而可能低于连续分配方案。</p>\n<p>伪代码层面的关键循环是：对 page table 中每个条目 <code>phys = table[i]</code>，以 <code>phys * S_page</code> 为基址加载该页 K/V 分块，累加进 online softmax 的状态。这里的工程取舍是 page 尺寸标定：$P$ 需要与 tensor core 的分块形状、片上 SRAM 容量对齐，使一次 page 搬运恰好填满一个计算分块，否则 gather 的收益被零碎的 DMA 吃掉。对高并发场景，多个请求的 page table 并行遍历，寻址开销随并发线性增长，这是 page 机制相对连续分配多付的那部分固定成本。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-10\">十 · 专家热度统计与分层驻留</h3>\n<p>与 KV 流动并行的是权重侧的数据流。每个 MoE 层在路由完成后，被选中的专家索引被计数，热度表按访问频次累加，异步更新——更新不在 decode 关键路径上同步完成，而是攒批后写入。输入是路由结果（每 token 的 top-k 专家 id），输出是更新后的热度排序与常驻集合 $\\mathcal{H}$。代价是统计本身要占一点带宽与一次小的元数据写，但真正的代价在下游：热度表的滞后性意味着 $\\mathcal{H}$ 的调整慢于真实路由分布的变化。</p>\n<p>命中率定义为：</p>\n<div class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>材料给出的定性锚点是 decode 阶段热专家命中率通常超过 90%。这个数字的工程含义是：绝大多数 token 的专家计算不需要 host-device 拷贝，冷专家的换入是低频事件。但低频不等于无代价——一旦某层路由突然偏向被换出的冷专家，该 token 的专家权重必须从 host 内存预取回 HBM，拷贝串行插入 decode 关键路径，单 token 时延出现尖峰。这就是失败模式的核心：命中率的均值好看，尾部却由路由分布的突变决定，而 TPOT SLO 恰恰约束的是尾部。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-11\">十一 · 水位越限：KV 换出与权重降级的优先级裁决</h3>\n<p>当池水位越过阈值，机制必须在两种收缩手段之间裁决：换出 KV page，还是降级专家权重（把部分热专家移出 $\\mathcal{H}$）。输入是当前水位、各请求的 SLO 余量、热度表；输出是一组被换出的 page 或被降级的专家，以及更新后的池账目。裁决原则是优先保 KV 以满足延迟 SLO——因为 KV 换出直接影响正在 decode 的请求，而权重降级影响的是未来可能被路由到的专家，两者的时延暴露面不同。</p>\n<p>代价在这里最集中：KV page 换出到 host 再换回，是纯带宽开销，且换回的时机难以精确预判；专家权重降级则把一次性的权重加载成本摊到后续命中该专家的 token 上。两种手段若阈值设置不当会互相触发——KV 换出腾出的空间被新请求迅速填满，水位再次越限，又触发权重降级，降级后冷专家被路由命中导致预取，预取又挤占 KV 空间，形成换入换出震荡，把显存利用率提升（材料称 20–40%）整个抵消在拷贝开销里。工程上，阈值需要带迟滞（hysteresis），且换出决策要参考请求的剩余生成长度：接近结束的请求其 page 换出后大概率不再被读，是低成本的换出候选。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-12\">十二 · 请求结束：page 归还与热度表异步收敛</h3>\n<p>请求完成生成后，其全部 page 归还池的空闲链表，page table 释放，池水位下降。输入是结束信号与 page table，输出是回收的物理页与更新后的空闲计数。代价很小但并非零：归还的 page 内容未清，下一次分配直接覆写，这要求分配器保证归还与再分配之间没有正在进行的 gather 引用该页——引用计数或 epoch 机制在此处必不可少，否则会出现读到上一请求残留 K/V 的正确性问题。</p>\n<p>与此同时，热度表在后台异步收敛：本请求贡献的专家访问计数被并入全局热度，$\\mathcal{H}$ 可能在下个调度周期被重算。这一步的工程判断是：热度更新的时间常数要与路由分布的漂移速度匹配。太快，$\\mathcal{H}$ 随噪声抖动，频繁换入换出；太慢，路由已经迁移而常驻集合还停在旧分布上，命中率下滑、时延尖峰出现。把热度表更新与 page 归还解耦——前者异步、后者同步——是这套机制能在 decode 关键路径上保持干净的前提；而 page 尺寸与水位阈值这两个标定参数，决定了同一套机制在长上下文与高并发混合负载下究竟是省下了显存还是只省下了账面数字。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-13\">十三 · 边界条件：配额不等式何时失效、page 粒度何时反噬、水位阈值何时震荡</h3>\n\n<p>这套机制成立的前提是一条硬性配额不等式：<span class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</span>其中 <span class=\"formula\">$\\mathcal{H}$</span> 是常驻热专家集合。它失效的方式不是\"显存不够\"这么笼统，而是三个具体方向。其一，请求进入时按<strong>最大生成长度</strong>预留 page 数，这是最保守的预留策略：预留量由 max_new_tokens 而非期望输出决定，当实际输出远短于上限时，预留的 page 在请求生命周期内被锁死，池中可分配 page 数被系统性高估占用，并发上限被压低。其二，热专家集合 <span class=\"formula\">$\\mathcal{H}$</span> 的大小是离线或准静态标定的，而路由分布随输入域漂移；一旦真实流量偏向被划入冷层的专家，命中率从 >90% 掉下来，换入拷贝直接插进 decode 关键路径。其三，page 尺寸 <span class=\"formula\">$S_{\\text{page}}$</span> 标定过小，page table 条目数与间接寻址开销同步上升，attention kernel 每次 gather 的有效载荷变薄，长上下文场景下吞吐反而低于连续分配——这是\"消除碎片\"换来的代价在另一个维度上重新出现。</p>\n\n<p>把失效条件按数据流顺序摊开，每一步的输入输出与代价可以列成一张对照表。注意代价列里没有一项是零成本的：分页把外部碎片换成了间接寻址，分层驻留把 HBM 压力换成了 host-device 带宽压力。</p>\n\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入 → 输出</th><th>系统代价</th><th>失效触发点</th></tr></thead><tbody><tr><td>请求准入预留</td><td>max_new_tokens → 预留 page 数</td><td>预留 page 在请求期内不可复用，压低并发上限</td><td>输出长度分布严重右偏，预留远大于实际</td></tr><tr><td>page 分配</td><td>page 请求 → 池中非连续 page</td><td>page table 条目写入，元数据随并发线性增长</td><td>池水位逼近阈值，分配开始等待换出</td></tr><tr><td>attention gather</td><td>page table → 按页粒度 IO</td><td>地址计算复杂化，小 page 时 IO 效率下降</td><td>page 过小，间接寻址开销占比升高</td></tr><tr><td>专家热度统计</td><td>访问频次 → 热度表（异步更新）</td><td>统计窗口滞后于路由突变</td><td>热度表更新慢于流量域切换</td></tr><tr><td>冷专家预取</td><td>路由命中冷专家 → host→device 拷贝</td><td>拷贝串行插入 decode，单 token 时延尖峰</td><td>路由集中到刚被换出的专家</td></tr><tr><td>水位超阈值处置</td><td>池水位 → KV page 换出 / 专家降级</td><td>换出与降级互相触发，形成震荡</td><td>阈值设置不当，两者反复抖动</td></tr></tbody></table>\n\n<p>最需要工程警觉的是<strong>震荡</strong>这一失效模式，它的机理是正反馈而非单点故障。池水位越过阈值 → 触发 KV page 换出 → 释放的 HBM 被专家权重回填 → 新请求到达又需要 KV page → 水位再次越阈 → 这次降级专家权重 → 冷专家被换出后紧接着被路由命中 → 预取拷贝占用带宽并推高时延 → 调度器为保 TPOT 又倾向于多留 KV → 水位继续爬升。两个动作各自看都合理，耦合起来就把 20–40% 的利用率增益吃回去，拷贝开销抵消了碎片消除的收益。判断是否进入震荡，看的是换出/换入事件在时间窗内的交替频率，而不是绝对水位值；阈值应当带迟滞区间，且 KV 换出与专家降级要有明确的优先级次序，不能由同一个水位信号同时驱动。</p>\n\n<p>量化这套方案的收益边界，可以用命中率公式反推拷贝代价的容忍上限：<span class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</span>设单 token 需访问 <span class=\"formula\">$k$</span> 个专家，未命中比例为 <span class=\"formula\">$1-\\text{hit rate}$</span>，则每 token 期望拷贝字节约为 <span class=\"formula\">$(1-\\text{hit rate})\\cdot k \\cdot \\bar{W}_e$</span>，这部分字节必须走 host-device 链路，其带宽远低于 HBM。当命中率从 >90% 掉到较低水平时，拷贝字节数按比例放大，而 decode 是逐 token 串行的，拷贝无法像预填那样被大批量摊薄——这正是\"尖峰击穿 TPOT SLO\"的算术来源。因此适用边界应表述为：热专家集合必须覆盖流量主体分布，且热度表更新周期显著短于流量域切换的时间尺度；否则应退回纯专家卸载或扩大常驻集合，而不是继续压 page 尺寸去挤显存。page 尺寸的标定同理，它的下限由 attention kernel 单次 gather 的有效载荷与 page table 条目开销的比值决定，而不是由\"能塞进多少 page\"决定。</p>\n<h3 id=\"alg-paged-kv-moe-sec-14\">十四 · 配额不等式：把“争抢”写成一条可解的约束</h3>\n<p>统一显存池的全部推导起点是那条容量不等式。把它写成等式形式更便于工程落地：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>逐项拆开看：$\\mathcal{H}$ 是常驻热专家集合，$W_e$ 是单专家权重字节，二者乘积是“权重侧”的硬占用；$N_{\\text{page}}$ 是当前已分配 KV page 数，$S_{\\text{page}}$ 是单 page 字节，乘积是“状态侧”的硬占用。注意这条不等式里没有“碎片”项——这正是分页的收益所在：连续分配时真实占用是 $\\sum_i \\lceil L_i \\rceil$ 向上取整后的和，而分页后占用精确等于 $N_{\\text{page}} \\cdot S_{\\text{page}}$，外部碎片被结构性消除。推导的关键一步在于把 $N_{\\text{page}}$ 与请求的预留策略绑定：请求进入时按最大生成长度预留，则</p>\n<div class=\"formula\">$$N_{\\text{page}} = \\sum_{r \\in \\text{active}} \\left\\lceil \\frac{L_r^{\\text{prompt}} + L_r^{\\text{maxgen}}}{P} \\right\\rceil$$</div>\n<p>其中 $P$ 是单 page 覆盖的 token 数。这一步把“并发数”翻译成了“page 数”，于是配额问题退化为一个二元决策：给定 $M_{\\text{HBM}}$，选择 $|\\mathcal{H}|$ 与 $N_{\\text{page}}$ 的切分点。工程上这个切分点不是静态的，而是由池水位驱动的动态量——水位越过阈值时，先降 $|\\mathcal{H}|$ 还是先降 $N_{\\text{page}}$，取决于当前 SLO 缺口落在 TTFT 还是 TPOT 上。代价是明确的：每多保留一个热专家，就少掉 $\\lfloor W_e / S_{\\text{page}} \\rfloor$ 个 page 的 KV 容量，反之亦然；这个换算比是容量规划时唯一需要记住的常数。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-15\">十五 · 命中率公式：热度统计的可计算形式</h3>\n<p>热专家集合 $\\mathcal{H}$ 不是拍脑袋选的，它由访问频次统计导出。给定一段观测窗口内各专家被路由的令牌数 $n_e$，命中率为：</p>\n<div class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>这个式子的分子是“落在常驻集合内的令牌数”，分母是窗口内总令牌数，因此它直接度量了“有多少比例的专家调用不需要 host-device 拷贝”。把 $\\mathcal{H}$ 取为按 $n_e$ 降序排列的前 $k$ 个专家，命中率就是 $n_e$ 分布的顶部累积质量；这也解释了为什么材料给出的 decode 阶段命中率通常 >90%——MoE 路由在 decode 阶段的分布远比 prefill 阶段集中，少数专家吃掉绝大多数令牌。推导的关键一步是把“选集合”转化为“排序后取前缀”：</p>\n<div class=\"formula\">$$\\mathcal{H} = \\arg\\max_{|S|=k} \\sum_{e \\in S} n_e \\;\\Rightarrow\\; \\mathcal{H} = \\text{top-}k\\big(\\{n_e\\}\\big)$$</div>\n<p>因为目标函数对集合是可加的，贪心取 top-$k$ 即为最优，无需组合搜索。伪代码落到可实现层面，热度表更新是异步的：</p>\n<ul>\n<li>每个 decode step 结束时，路由模块把本 step 的专家计数累加进一个分片计数器（按 expert id 取模分片，避免全局锁）；</li>\n<li>后台线程按固定周期把分片计数器归并成全局 $n_e$，做指数滑动平均以抑制突发抖动；</li>\n<li>按平滑后的 $n_e$ 排序，取前缀得到新的 $\\mathcal{H}'$，与当前 $\\mathcal{H}$ 求差集，只对差集做换入换出；</li>\n<li>换入换出走独立的拷贝流，与计算流用事件同步，避免插入 decode 关键路径。</li>\n</ul>\n<p>系统代价在这里体现为带宽：一次换入一个专家是 $W_e$ 字节的 host-to-device 传输，若窗口内路由分布发生漂移，差集规模变大，拷贝带宽就会与 KV page 的 gather IO 争抢同一条 HBM 通道。命中率公式的价值在于它给出了一个可监控的量——命中率下滑先于 TPOT 恶化出现，可作为扩容或调整 $k$ 的前置信号。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-16\">十六 · Page table gather：attention 侧的开销推导</h3>\n<p>分页 KV 的 attention 不再是对连续缓冲区的切片，而是按 page table 做 gather。设一个请求的 KV 分布在 $m$ 个 page 上，逻辑位置 $t$ 映射到物理 page $p(t)=\\text{table}[\\lfloor t/P \\rfloor]$ 与页内偏移 $t \\bmod P$。FlashAttention 以 page 为粒度做 IO，意味着每个 page 触发一次独立的访存事务序列，其有效带宽可写成：</p>\n<div class=\"formula\">$$\\text{eff. BW} \\approx \\frac{P \\cdot S_{\\text{token}}}{P \\cdot S_{\\text{token}} + c_{\\text{addr}} + c_{\\text{lat}}} \\cdot \\text{BW}_{\\text{peak}}$$</div>\n<p>$S_{\\text{token}}$ 是单 token 的 KV 字节，$c_{\\text{addr}}$ 是地址计算开销，$c_{\\text{lat}}$ 是页切换的固定延迟。这个式子的含义很直接：$P$ 越小，分母中的常数项占比越大，有效带宽越低。这就是“小 page 时 IO 效率下降”的定量来源，也是 page 尺寸标定的核心权衡——$P$ 增大提升 IO 效率，但增大内部碎片（最后一个 page 的浪费）并抬高预留粒度。伪代码层面，gather 的实现要点是预计算而非在内层循环里做除法：</p>\n<ul>\n<li>为每个请求预生成 page 索引数组与页内偏移数组，长度等于当前 KV 长度；</li>\n<li>attention 外层按 page 遍历，内层对页内 $P$ 个 token 做连续访存，把间接寻址压缩到页粒度；</li>\n<li>page table 与索引数组放在片上可缓存的位置，避免每次 tile 重新读取；</li>\n<li>对共享前缀的请求做 page 级引用计数，前缀 page 只读共享，写时复制。</li>\n</ul>\n<p>代价落在延迟上：地址计算从“基址加偏移”退化为“查表加偏移”，在 decode 阶段每 token 都要走一遍，若 page 过小，这部分开销在 TPOT 中的占比会显著上升，长上下文请求的吞吐反而可能低于连续分配方案。这是分页方案必须用标定实验确认的边界，而不是默认收益。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-17\">十七 · 水位阈值与震荡：把换出策略写成状态机</h3>\n<p>统一显存池的稳定性完全取决于水位阈值的设定。设池占用率为 $\\rho = (\\sum_{\\mathcal{H}} W_e + N_{\\text{page}} S_{\\text{page}})/M_{\\text{HBM}}$，策略是双阈值带滞回：高水位 $\\rho_{\\text{hi}}$ 触发换出，低水位 $\\rho_{\\text{lo}}$ 触发停止换出，二者之间是死区。若 $\\rho_{\\text{hi}}$ 与 $\\rho_{\\text{lo}}$ 过近，KV page 换出与专家权重降级会互相触发：换出专家腾出的空间被新 page 立刻占满，水位再次越线，又触发下一轮换出，形成换入换出震荡，拷贝开销把利用率收益吃掉。推导的关键一步是把“一次换出释放多少空间”与“一次换出花多少时间”对比：</p>\n<div class=\"formula\">$$\\text{amortized cost} = \\frac{W_e}{\\text{BW}_{\\text{h2d}}}, \\quad \\text{benefit} = \\frac{W_e}{S_{\\text{page}}}\\ \\text{pages}$$</div>\n<p>只有当被释放的 page 能在换出完成前被有效利用（即确实有排队请求需要这些 page），这次换出才是正收益；否则就是纯开销。因此阈值策略必须与请求队列状态联动，而不是只看水位。伪代码上，换出决策是一个带优先级的循环：</p>\n<ul>\n<li>按“最近最少使用 + 当前队列中是否有请求路由到它”给每个非驻留专家打分；</li>\n<li>优先换出分数最低且短期无请求命中的专家，避免换出后立刻被需要；</li>\n<li>KV page 换出优先选择已结束请求的 page 与长上下文中靠前、短期内不会被重新注意的 page；</li>\n<li>每次换出后记录实际拷贝耗时，回填到阈值调节器，动态拉开 $\\rho_{\\text{hi}}$ 与 $\\rho_{\\text{lo}}$ 的间距。</li>\n</ul>\n<p>失败模式的形态是明确的：路由分布突变使请求集中到刚被换出的冷专家，host-device 拷贝串行插入 decode 关键路径，单 token 时延出现尖峰并击穿 TPOT SLO。防御手段不是取消换出，而是给换出加“冷却期”——刚换出的专家在冷却期内不参与下一轮换出候选，同时预取队列对其提高优先级。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-18\">十八 · 预留与归还：page 生命周期的可实现路径</h3>\n<p>请求进入时按最大生成长度预留 page 数，这个“预留”必须是逻辑预留而非物理分配，否则高并发下预留本身就会耗尽池子。实现上把 page 分为三态：free、reserved、committed。reserved 只占计数不占物理页，committed 才真正从池中取页。于是实际物理占用为：</p>\n<div class=\"formula\">$$N_{\\text{page}}^{\\text{phys}} = \\sum_{r} \\min\\big(L_r^{\\text{cur}},\\ L_r^{\\text{prompt}} + L_r^{\\text{maxgen}}\\big) \\Big/ P$$</div>\n<p>其中 $L_r^{\\text{cur}}$ 是请求当前已生成的 token 数。这个式子的工程含义是：物理占用随生成进度增长，而不是在请求进入瞬间跳到最大值，因此池子的瞬时压力被摊平到整个 decode 过程。代价是预留计数可能超过物理容量，需要在 committed 阶段做准入控制——当物理页不足时，新请求排队或降级为更小的最大生成长度，这直接影响 TTFT。请求结束后 page 归还池，归还路径必须与热度表更新解耦：page 归还是同步的、在请求完成回调里立即执行；热度表更新是异步的、在后台线程里批量执行。两者混在一起会让请求完成路径变长，抬高尾延迟。工程判断上，page 尺寸 $P$ 的标定应取“使 $c_{\\text{addr}} + c_{\\text{lat}}$ 相对 $P \\cdot S_{\\text{token}}$ 可忽略”的最小值，再用长上下文吞吐做回归验证；配额切分点则应由命中率与 TPOT 两个监控量共同驱动，而不是固定比例。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-19\">十九 · 统一显存池的可行域：配额不等式、失效边界与拷贝代价</h3>\n\n<p>把权重与 KV 放进同一个池，本质是把两个原本独立增长的量塞进一条硬约束里。逐项看核心不等式 $M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$：左端是物理 HBM 减去运行时不可让渡的部分（激活、通信缓冲、kernel workspace、框架自身开销），这个\"可用池\"才是真正能分配的额度，工程上必须显式扣出来，否则水位阈值永远算不准；右端第一项是常驻热专家集合 $\\mathcal{H}$ 的权重字节总和，第二项是已分配 page 数与单 page 字节之积。推导的关键一步在于把\"预留\"与\"实占\"分开：请求进入时按最大生成长度预留 $N_{\\text{reserve}}$ 个 page，但池中真正被写满的只有已解码 token 对应的 page，于是可行域应写成 $\\sum_{e\\in\\mathcal{H}} W_e + N_{\\text{reserve}}\\cdot S_{\\text{page}} \\le M_{\\text{pool}}$ 作为准入判据，而 $\\sum_{e\\in\\mathcal{H}} W_e + N_{\\text{filled}}\\cdot S_{\\text{page}} \\le M_{\\text{pool}}$ 作为运行期水位判据。两者的差额就是池的\"安全垫\"，它决定了能同时容纳多少条长上下文请求而不触发换出。若只按实占判据准入，突发并发会在解码中途把池撑爆，换出被迫插入 decode 关键路径。</p>\n\n<p>边界条件由此可以直接读出。第一，$\\mathcal{H}$ 的大小受限于权重总量与 page 需求的比值：当并发请求的平均上下文长度上升，$N_{\\text{reserve}}$ 单调增长，$\\mathcal{H}$ 必须收缩，热专家命中率随之下降——材料给出的 >90% 是 decode 阶段的典型命中率，它成立的前提是路由分布相对稳定且批内 token 分散在较多专家上；一旦路由集中到少数专家，$\\mathcal{H}$ 反而可以更小，但被踢出的专家会在下一批突然变成热点。第二，page 尺寸 $S_{\\text{page}}$ 存在双向夹逼：page 过小，page table 间接寻址在 attention kernel 里的地址计算占比升高、FlashAttention 以 page 为粒度的 IO 效率下降，长上下文吞吐反而可能低于连续分配；page 过大，内部碎片回升，长请求尾部浪费的 page 空间抵消了消除外部碎片的收益。第三，池水位阈值若贴近可行域上界，KV page 换出与专家降级会互相触发形成震荡：换出权重腾出的空间立刻被新 page 占满，新 page 又推高水位迫使更多权重降级，拷贝开销把 20–40% 的利用率增益吃掉。</p>\n\n<p>落到可实现层面，准入与换出的判定必须是一个带优先级的单遍扫描，而不是两套独立逻辑。伪代码思路：请求到达时计算 $N_{\\text{reserve}}$，若 $\\sum_{e\\in\\mathcal{H}} W_e + N_{\\text{reserve}}\\cdot S_{\\text{page}} &gt; M_{\\text{pool}}$，先按\"最近最少使用 + 热度低于阈值\"的顺序把冷专家标记为可降级，再检查降级后是否满足；仍不满足则拒绝或排队，绝不通过换出已填充 page 来腾空间——已填充 page 属于在途请求的活跃状态，换出它等于把 host-device 拷贝塞进 decode 路径。运行期水位越过软阈值时，只做两件事：把热度表尾部专家异步降级、把已结束请求的 page 立即归还。热度表更新走异步路径，避免在 token 循环里做统计。</p>\n\n<p>系统代价集中在冷专家的换入换出。路由突然偏向被换出的冷专家时，host-device 拷贝串行插入 decode 关键路径，单 token 时延出现尖峰并击穿 TPOT SLO——这是本方案最典型的失效模式，且它不可通过提高水位阈值消除，只能靠预取窗口与路由预测缓解。表观代价还包括 page table 间接寻址带来的 kernel 复杂度：gather 式 KV 读取让地址计算从线性偏移变成多级查表，小 page 时每次 IO 的有效载荷下降，带宽利用率被查表开销稀释。因此工程判断是：page 尺寸按 attention kernel 的单次 IO 粒度标定，宁大勿小；热专家集合 $\\mathcal{H}$ 留出可降级余量而非顶满；准入判据用预留量而非实占量。三者共同决定这套共存方案能否在长上下文与高并发混合负载下稳定落在 20–40% 利用率增益区间内。</p>\n<h3 id=\"alg-paged-kv-moe-sec-20\">二十 · 请求形态决定配额是否成立</h3>\n<p>统一显存池的配额关系 \\(M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}\\) 只有在负载形态与它匹配时才是一个可解的不等式。分页 KV 与热专家常驻共存的收益，来自两类占用在时间尺度上的错位：KV page 的生命周期跟随请求，从预填到生成结束才归还；热专家集合的生命周期跟随路由分布，以远长于单请求的节奏变化。当请求形态是“长上下文与高并发混合的在线服务”时，这两个时间尺度天然分离，池子可以按水位在两者之间腾挪。反之，如果请求形态让 KV 占用的波动周期逼近专家热度表的更新周期，配额就退化为一个不断被打破又重建的约束，池子管理开销吃掉全部收益。</p>\n<p>具体机制上，请求进入时按最大生成长度预留 page 数，这个“按最大”的动作本身就是负载配方的函数。生成长度分布若重尾，预留量与实际消耗量的比值决定了池子的瞬时占用峰值；若请求的实际输出远短于预留，page 在请求结束前无法被别的请求复用，池子的有效容量被系统性高估。因此适合这套机制的负载，是输出长度分布相对可预测、或者至少上界与均值差距可控的在线服务；对输出长度完全不可预知的开放域生成，按最大预留会把池水位长期顶在阈值附近，触发频繁的换出与降级。</p>\n<p>代价落在延迟上：预留过多 page 抬高池水位，水位超阈值即触发 KV page 换出或专家权重降级，而换出动作本身要占用 host-device 带宽，与 decode 阶段的权重预取争抢同一条链路。一个具体的工程判断是：当单请求预留 page 字节数乘以并发数已经接近池容量减去热专家权重总量时，这套机制在该负载下不再有腾挪空间，此时应改为按实际生成长度分段预留，把预留从“请求级”下沉到“块级”，代价是 page table 的更新频率上升。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-21\">二十一 · 长度分布与 page 尺寸的耦合</h3>\n<p>page 尺寸 \\(S_{\\text{page}}\\) 不是独立参数，它与长度分布共同决定 attention kernel 的 IO 效率。FlashAttention 以 page 为粒度做 IO，意味着一次 gather 的有效载荷是 \\(S_{\\text{page}}\\) 减去 page table 间接寻址的固定开销。长度分布若集中在中等长度，page 内 KV 的填充率高，间接寻址开销被摊薄；长度分布若两极分化——大量极短请求与少量超长请求并存——短请求的尾 page 大量半满，长请求的 page 数线性堆高，两者的 page table 遍历成本同时上升。</p>\n<div class=\"formula\">$$\\text{IO}_{\\text{eff}} = \\frac{S_{\\text{page}} \\cdot \\eta_{\\text{fill}}}{S_{\\text{page}} \\cdot \\eta_{\\text{fill}} + c_{\\text{addr}}},\\quad \\eta_{\\text{fill}} = \\frac{\\sum_i \\ell_i}{N_{\\text{page}} \\cdot S_{\\text{page}}}$$</div>\n<p>其中 \\(\\eta_{\\text{fill}}\\) 是 page 平均填充率，\\(c_{\\text{addr}}\\) 是单 page 地址计算的等效开销。这个式子说明：page 尺寸标定过小会让 \\(c_{\\text{addr}}\\) 占比升高，长上下文请求的吞吐反而低于连续分配方案；page 过大则短请求的 \\(\\eta_{\\text{fill}}\\) 塌陷，池子被半满 page 占据。适合这套机制的负载配方，是长度分布的主峰落在 page 尺寸的若干整数倍附近，使填充率维持在较高水平，同时超长请求的数量占比低到不足以让 page table 遍历成为 kernel 的瓶颈。</p>\n<p>系统代价体现在长上下文请求的 TTFT 上：预填阶段要按 page table gather 整段上下文，page 数越多，gather 的循环次数越多，地址计算在 SM 上的指令占比越高。一个具体例子是同一批并发下，把上下文长度从主峰附近推到数倍主峰，page 数按比例增长，而 gather 的有效带宽因间接寻址开销上升而下降，TTFT 的增长快于线性的上下文长度增长。这不是 page 机制的缺陷，而是负载偏离配方后的必然结果；判断标准是 page table 遍历开销是否已经超过 KV 数据本身的搬运开销。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-22\">二十二 · 并发与批大小的动态区间</h3>\n<p>批大小随并发动态变化，是连续批处理的常态，但对统一显存池而言，批大小是 KV page 分配速率的乘数。并发上升时，每个在途请求都持有一组 page，池水位以并发乘以单请求 page 数的速度爬升；批大小上升时，单次 decode 迭代要 gather 的 page 总数上升，attention kernel 的地址计算压力同步上升。两者叠加，池水位与 kernel 开销在同一时间窗口内同时恶化，这正是负载配方要避开的区间。</p>\n<p>适合的并发区间有一个可算的上界：把池容量减去热专家权重总量，再除以单请求平均 page 字节数，得到的是稳态并发上限。超过这个上限，池水位必然越过阈值，触发 KV page 换出或专家权重降级。由于机制规定优先保 KV 以满足延迟 SLO，超限时被牺牲的是专家权重，冷专家被换出到 host 内存，decode 阶段的权重预取进入关键路径。此时 TPOT 的稳定性不再由 attention 决定，而由 host-device 拷贝的带宽决定。</p>\n<p>代价的具体形态是 TPOT 的尾部抬升：批内只要有一个请求的路由落到被换出的冷专家，该 token 的 decode 就要串行插入一次拷贝，整批的迭代时间被这一个 token 拉长。并发越高，批内命中冷专家的概率越高，尾部抬升越频繁。因此这套机制的负载配方要求并发在一个使池水位长期低于阈值、且批内路由集中在热专家集合内的区间内运行；超过该区间，收益从显存利用率转移到拷贝开销上。工程上应把并发上限与热专家命中率 \\( \\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}\\) 一起监控，命中率下滑是并发越界的先行指标。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-23\">二十三 · 负载不对时的三种失效形态</h3>\n<p>第一种是路由分布突变。请求集中到被换出的冷专家，host-device 拷贝串行插入 decode 关键路径，单 token 时延出现尖峰并击穿 TPOT SLO。这种失效与并发无关，即使池水位很低也会发生，因为触发条件是热度表与实际路由的偏离，而非容量不足。热度表异步更新，更新周期内的路由漂移无法被及时捕捉，漂移幅度越大，尖峰越高。负载配方要求路由分布在一个更新周期内的变化幅度有限，否则这套分层驻留的假设不成立。</p>\n<p>第二种是 page 尺寸标定过小。attention kernel 地址计算与 IO 效率下降，page table 间接寻址开销占比升高，长上下文请求吞吐反而低于连续分配方案。这种失效在长度分布偏向长上下文时最明显，因为 page 数随上下文线性增长，间接寻址开销随之线性累积。它不会表现为错误，只表现为吞吐不达预期，因而容易被误判为 kernel 实现问题而非负载配方问题。</p>\n<p>第三种是水位阈值设置不当。KV page 换出与专家权重降级频繁抖动，两者互相触发形成换入换出震荡，显存利用率提升被拷贝开销抵消。阈值过低则池子长期满载、换出频繁；阈值过高则腾挪空间不足、突发并发直接击穿。震荡的判别特征是换出与换入在同一时间窗口内交替出现，且每次换出的对象在短时间内又被重新需要。负载配方要求并发与长度的波动幅度小于阈值所留出的余量，否则池子管理本身成为主要开销。</p>\n<table class=\"mini\"><thead><tr><th>失效形态</th><th>触发条件</th><th>观测指标</th><th>代价落点</th></tr></thead><tbody><tr><td>路由突变</td><td>热度表更新周期内路由漂移</td><td>热专家命中率下滑、TPOT 尾部尖峰</td><td>decode 关键路径插入拷贝</td></tr><tr><td>page 过小</td><td>长度分布偏长、填充率低</td><td>gather 地址开销占比、长上下文吞吐</td><td>TTFT 与预填带宽</td></tr><tr><td>阈值抖动</td><td>并发与长度波动超余量</td><td>换出换入交替频率</td><td>host-device 带宽、池管理开销</td></tr></tbody></table>\n\n<h3 id=\"alg-paged-kv-moe-sec-24\">二十四 · 配方与 SLO 双指标的对应</h3>\n<p>SLO 以 TTFT 与 TPOT 双指标约束，这两个指标恰好对应负载配方的两个维度。TTFT 由预填阶段的 page gather 效率与池水位决定：水位高时预填请求可能要先等待 page 换出腾出空间，TTFT 的抬升来自排队而非计算。TPOT 由 decode 阶段的专家权重驻留状态决定：热专家命中率高时 TPOT 平稳，命中率下滑时 TPOT 出现与拷贝同步的尖峰。因此配方不是一组固定参数，而是一组使两个指标同时可控的负载条件。</p>\n<p>具体机制上，按最大生成长度预留 page 数这一动作把 TTFT 与 TPOT 耦合起来：预留越多，池水位越高，预填排队风险越大，但同时 decode 阶段可用的 page 越充足、越不容易触发换出。配方要在这对矛盾中找到让两个指标都不越界的位置。一个可操作的判断是：当 TPOT 的尾部尖峰主要由拷贝引起而非 attention 引起时，说明专家权重配额被压得过紧，应上调热专家集合 \\(\\mathcal{H}\\) 的规模；当 TTFT 的抬升主要由排队引起时，说明 KV 配额被压得过紧，应下调预留策略或提高池容量。</p>\n<p>系统代价是显存利用率的可兑现程度。材料给出的显存利用率提升 20–40% 与 decode 阶段热专家命中率通常 >90%，是配方成立时的结果，而非任何负载下的保证。负载偏离配方时，这两个数字都会退化：利用率提升被拷贝开销抵消，命中率下滑使 TPOT 失去稳定性。因此容量规划应把这两个数字当作条件性收益，在负载画像确认后再据此定池容量与热专家集合规模，而不是反过来用收益数字去反推负载可以有多宽。</p>\n<p>落在具体机制上：热度表的更新周期与池水位阈值的余量应当由同一套负载画像标定——路由漂移幅度决定更新周期上限，并发与长度的波动幅度决定阈值余量下限，两者共同约束了这套共存机制能承接的请求形态边界。越过这条边界，分页 KV 与专家权重共存不再是显存效率手段，而是把延迟不确定性从 attention 转移到了 host-device 链路上。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-25\">二十五 · 负载配方与失效边界：这套共存方案在什么请求形态下才成立</h3>\n\n<p>这套方案的负载配方是<strong>长上下文与高并发混合的在线服务</strong>：批大小随并发动态变化，SLO 同时以 TTFT 与 TPOT 双指标约束，请求进入时按最大生成长度预留 KV page 数。它成立的隐含前提是请求长度分布相对可预期、专家路由在时间上平滑——热度表统计出的热专家集合能覆盖绝大多数 token 的专家访问。此时统一显存池按 SLO 动态分配配额，KV page 与热专家权重共享同一块 HBM，显存利用率提升 20–40%，decode 阶段热专家命中率通常 >90%。反过来，若负载是短请求、低并发、单条长上下文独占式推理，page 化的收益被 page table 间接寻址开销吃掉，分层驻留也失去意义——冷专家本来就很少被触及，换出换入的调度复杂度纯属净代价。配额关系必须始终满足</p>\n\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n\n<p>其中 $\\mathcal{H}$ 为常驻热专家集合。负载一旦偏离配方，这条不等式会从两端同时被挤压。</p>\n\n<p>第一类失效是<strong>路由分布突变</strong>。热度表按访问频次异步更新，天然滞后于真实路由；当请求集中到刚被换出的冷专家，host-device 拷贝被串行插入 decode 关键路径，单 token 时延出现尖峰并击穿 TPOT SLO。这不是偶发抖动，而是负载形态与热度统计窗口不匹配的结构性问题：突发流量、领域切换、多租户混跑都会让热专家集合在窗口内失效。工程判断是热度表更新周期必须与路由分布的漂移时间尺度对齐，并对冷专家预取设置提前量，否则 >90% 的命中率只在平稳负载下成立。</p>\n\n<p>第二类失效是<strong>page 尺寸标定过小</strong>。page table 间接寻址使 attention kernel 地址计算更复杂，小 page 时 IO 效率下降，地址计算与 page table 开销占比升高，长上下文请求吞吐反而低于连续分配方案——碎片消除的收益被 gather 开销抵消。page 过小会直接限制长上下文吞吐，这是该方案与连续分配方案交叉的性能拐点，标定时应以长上下文请求的 IO 粒度为下界，而非以碎片率为唯一目标。</p>\n\n<p>第三类失效是<strong>水位阈值设置不当引发的震荡</strong>。统一显存池水位超过阈值时触发 KV page 换出或专家权重降级，优先保 KV 以满足延迟 SLO；但若阈值过紧，KV page 换出与专家权重降级会互相触发，形成换入换出振荡，显存利用率提升被拷贝开销完全抵消，且两条路径的拷贝都落在关键路径上。阈值必须留出滞回区间，并把专家降级与 KV 换出的触发条件解耦——二者共享一个水位信号是震荡的根源。三类失效的共同点是：方案的收益来自“负载可预期 + 参数标定匹配”，一旦请求形态、路由分布或 page 粒度任一偏离配方，系统代价就从拷贝带宽与地址计算开销两端显性化。</p>\n<h3 id=\"alg-paged-kv-moe-sec-26\">二十六 · 硬件档位与三级存储的分工边界</h3>\n<p>本方案的硬件档位是单机三级存储：HBM、host 内存、NVMe。三者的角色不能混：HBM 是唯一被 attention kernel 与 MMA 直接寻址的空间，host 内存是冷专家权重的第一换出层，NVMe 是第二换出层。工程上必须先把“什么可以离开 HBM”定死，否则配额公式无从落地。可离开 HBM 的只有冷专家权重；KV page 一旦被换出到 host，decode 阶段的 gather 就要跨 PCIe 取数，单 token 时延立刻被拉长，因此 KV page 的换出只能是水位告警下的应急手段，而不是常态策略。</p>\n<p>档位划分的依据是常驻热专家集合的字节数。设热专家集合为 $\\mathcal{H}$，则 HBM 必须容纳的下限是：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>这条不等式是整个部署配方的骨架。它说明两件事：热专家集合的大小直接决定还剩多少 page 预算；而 page 预算乘以单 page 字节就是可支撑的并发 KV 容量。工程判断的顺序因此是反的——先按目标并发与最大生成长度算出 $N_{\\text{page}} \\cdot S_{\\text{page}}$，再把剩余 HBM 全部划给热专家，剩下的专家一律下沉。若剩余空间装不下按热度排序的前若干专家，就必须降低并发目标或缩小 page 尺寸，二者必居其一。</p>\n<p>三级存储的带宽梯度决定了预取必须提前。冷专家从 host 换入的拷贝若串行插入 decode 关键路径，就是本方案最典型的时延尖峰来源。因此部署时必须为每个 MoE 层预留至少一个 token 步的预取窗口：路由结果在上一层末尾即可部分预测，预取指令应在当前层计算尚未结束时发出，使拷贝与计算重叠。NVMe 层只应承载访问频次极低的专家，任何从 NVMe 发起的同步换入都应被视为配置错误。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-27\">二十七 · 并行拓扑：专家并行度与 page 池的耦合</h3>\n<p>材料未给出并行拓扑，但配额公式本身约束了拓扑选择。统一显存池是每卡独立的，page 池不能跨卡共享，因此张量并行（TP）会把 KV page 按头维切分到各卡，每卡只持有 $1/TP$ 的 KV 字节；专家并行（EP）则把专家权重按专家维切分，每卡只常驻自己负责的热专家。两者的显存账本完全不同，必须分开算。</p>\n<p>在 EP 拓扑下，每卡的常驻热专家集合是全局热集合的子集，配额公式退化为按卡计算：</p>\n<div class=\"formula\">$$M_{\\text{HBM}}^{(r)} \\ge \\sum_{e \\in \\mathcal{H} \\cap \\mathcal{E}_r} W_e + N_{\\text{page}}^{(r)} \\cdot S_{\\text{page}}$$</div>\n<p>其中 $\\mathcal{E}_r$ 是第 $r$ 张卡负责的专家集合。这意味着热度统计必须是全局的，而驻留决策是局部的——热度表按全局访问频次排序，但每卡只在自己负责的专家里挑热的常驻。若某张卡分到的专家恰好都是冷的，它的 HBM 会大量闲置，而别的卡却在告警，这就是 EP 拓扑下最隐蔽的负载不均。部署时应把热度表与专家到卡的映射一起做静态校准，使每卡的热专家字节数大致均衡。</p>\n<p>代价体现在 All-to-All 与 page 池的争抢上。EP 下每个 token 的专家分发要走 All-to-All，通信缓冲本身占用 HBM；若 page 池把这块空间也算进去，水位阈值就会过早触发。工程上应把通信缓冲作为固定预留从池中扣除，而不是让它在水位统计里浮动。TP 拓扑下没有这个问题，但 TP 会把 page 池切得很碎，单卡 page 数变少，page table 间接寻址的相对开销上升，长上下文吞吐受小 page 效率的制约更明显。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-28\">二十八 · 量化方案与 page 尺寸的联合标定</h3>\n<p>量化方案材料未给出，但量化直接改变公式里的两个量：$W_e$ 与 $S_{\\text{page}}$。权重从高精度降到 NVFP4/FP8 量级，$W_e$ 成比例缩小，同样的 HBM 能常驻更多热专家，热专家命中率随之上升；KV 若也做低精度存储，$S_{\\text{page}}$ 缩小，同等 page 预算能覆盖更长上下文。两者不是独立的——权重压得越狠，留给 KV 的空间越多，page 就可以标得更大，而大 page 恰好缓解 page table 间接寻址的开销。</p>\n<p>page 尺寸的标定是一个双边约束问题。page 太小，attention kernel 按 page table gather 时地址计算占比升高，IO 效率下降，长上下文吞吐反而低于连续分配；page 太大，内部碎片回升，长请求末尾的浪费页变多，等于把外部碎片换成了内部碎片。可复现的标定思路是：以目标上下文长度为上限，取 page 字节为 $S_{\\text{page}} = 2 L_{\\text{chunk}} H d$ 的形式，其中 $L_{\\text{chunk}}$ 是单 page 覆盖的 token 数，然后实测 gather 的地址计算开销与碎片浪费，在两者之和最小处定档。材料只给出定性结论——page 过小会限制长上下文吞吐——因此标定必须落在实测上，不能拍脑袋取 16 或 32 这类习惯值。</p>\n<p>量化与 page 的联合代价是显存带宽。低精度 KV 让单 token 的 KV 读取字节下降，decode 的带宽压力缓解；但 gather 是不连续的，低精度下每次 gather 的有效载荷更小，带宽利用率反而可能下降。这就是为什么量化方案必须与 page 尺寸一起标定：单独压精度而不动 page，可能换来更差的 IO 效率。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-29\">二十九 · KV 策略：预留、换出与归还的时序</h3>\n<p>KV 策略的核心是“按最大生成长度预留”。请求进入时一次性预留 $N_{\\text{page}}^{\\text{req}} = \\lceil L_{\\text{max}} / L_{\\text{chunk}} \\rceil$ 个 page，而不是边生成边申请。预留制的好处是准入控制简单：池中剩余 page 数不足即拒绝或排队，不会出现生成到一半才发现无 page 可用的窘境。代价是预留即占用，短请求也会按最大长度占住 page，实际利用率低于名义值——这正是需要水位阈值来回收的原因。</p>\n<p>换出的触发条件是池水位超过阈值。策略上必须区分优先级：KV page 换出优先于专家权重降级，因为前者影响的是已经在跑的请求的 TPOT，后者影响的是未来请求的专家命中率。但材料明确指出，水位阈值设置不当会让两者互相触发形成震荡——KV 换出腾出的空间被专家预取立刻填满，预取又把水位推高再次触发 KV 换出。可复现的做法是给两类操作设不同的滞回区间：KV 换出在高水位触发、低水位停止；专家降级在更高水位触发，且降级后的专家在热度表更新周期内不得立即回升。</p>\n<p>归还发生在请求结束。page 归还池后立即可被下一个请求分配，但由于不要求物理连续，归还的 page 会散落在池中，page table 的映射项随之碎片化。工程上应维护空闲 page 链表而非位图，使分配为 $O(1)$；同时热度表的异步更新必须与归还解耦，避免请求结束的瞬间触发大量专家换入。这里的系统代价是显存碎片的管理开销：page 本身固定大小，外部碎片已被消除，但 page table 项数与并发请求数成正比，长上下文高并发时 page table 自身的显存占用不可忽略。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-30\">三十 · 调度参数：批大小、SLO 与配额的联动</h3>\n<p>调度参数里最关键的三个是批大小上限、TTFT/TPOT 双 SLO、以及池水位阈值。三者通过 page 预算耦合：批大小决定同时在跑的请求数，请求数乘以每请求预留 page 数就是 page 需求峰值；SLO 决定水位告警时优先保谁；水位阈值决定换出频率。材料未给出具体批大小与 SLO 数值，因此配方只能给出联动关系而非定值。</p>\n<p>可复现的配置思路是参数扫描而非单点调优。固定硬件档位与量化方案后，以批大小上限为横轴、以热专家常驻比例为纵轴，测出满足 TPOT SLO 的可行域边界。边界左侧是 page 不足导致的排队，右侧是专家换入导致的时延尖峰。可行域内再按显存利用率排序，取利用率最高且离边界有余量的点。这个扫描的代价是时间：每个点都要跑长上下文与高并发混合的负载，因为纯长上下文测不出换出震荡，纯高并发测不出 page 碎片。</p>\n<p>调度器还必须处理路由分布突变。失败模式已经写明：请求集中到被换出的冷专家时，host-device 拷贝串行插入 decode 关键路径，单 token 时延尖峰击穿 TPOT SLO。缓解手段不是提高预取量，而是给热度表加突变检测——当某专家的瞬时访问频次相对其历史均值跃升超过设定倍数时，提前将其升格为常驻并预取其权重，用一次性的显存占用换取尖峰的消除。这一步的显存代价是短暂的，但必须计入水位统计，否则又会触发 KV 换出。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-31\">三十一 · 一个可复现的配置流程</h3>\n<p>把上述约束串成流程，得到可复现的配置步骤，每一步都对应一个可测量的量：</p>\n<ul>\n<li>定并发与上下文目标，算出每请求预留 page 数 $N_{\\text{page}}^{\\text{req}}$，乘以并发上限得到 page 字节需求。</li>\n<li>从 HBM 总量中扣除通信缓冲与运行时固定开销，剩余部分减去 page 需求，得到热专家字节预算。</li>\n<li>按全局热度表排序专家，在每卡负责的专家集合内取前缀，使前缀字节和不超过该卡的热专家预算，得到 $\\mathcal{H} \\cap \\mathcal{E}_r$。</li>\n<li>标定 page 尺寸：在候选 $L_{\\text{chunk}}$ 上实测 gather 地址开销与碎片浪费之和，取最小点。</li>\n<li>设水位阈值与滞回区间，KV 换出与专家降级分级触发，降级后设冷却期。</li>\n<li>以批大小为横轴扫描可行域，取利用率最高且留有余量的调度点。</li>\n</ul>\n<p>流程的每一步都有对应的验证指标：page 需求对应用户可见的并发上限，热专家预算对应 decode 阶段的热专家命中率（材料给出通常 &gt;90%），page 尺寸对应长上下文吞吐，水位阈值对应换出频率与 TPOT 尖峰次数。显存利用率的提升（材料给出 20–40%）是这些步骤全部到位后的结果，而不是单独某一项调参能拿到的。任何一步跳过，收益都会被另一处的拷贝开销或碎片浪费抵消——这正是统一显存池方案与纯专家卸载方案的分水岭：前者按 SLO 动态分配配额，后者让权重与 KV 各自独立管理，配额冲突无人裁决。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-32\">三十二 · 配方失效的三种边界：路由突变、page 过小、水位抖动</h3>\n<p>这套配方的前提是“热度可预测”。热度表按访问频次异步更新，本质是对路由分布做滞后估计；一旦路由分布突变（微调后的新领域流量、对话主题漂移、某类 token 集中触发少数专家），请求会成批落到已被换出的冷专家上，host-device 拷贝被串行插入 decode 关键路径。此时单 token 时延不再由 MMA 或 attention 决定，而由一次 PCIe 往返决定，TPOT SLO 被直接击穿。工程上的判别量是“预取命中率”而非“热专家命中率”：>90% 的命中率只说明稳态成立，不说明突变时安全；应监控单位时间内被换出专家集合的访问增量，超过阈值即冻结降级、把配额临时还给专家侧。代价是这段时间 KV page 被压缩，长上下文请求排队，TTFT 上升——这是用 TTFT 换 TPOT 的显式取舍。</p>\n<p>第二个边界在 page 尺寸。page table 间接寻址把 attention kernel 的地址计算从线性偏移变成 gather，FlashAttention 以 page 为粒度做 IO，page 越小，碎片越少但每次 IO 的有效载荷越低，地址计算与描述符开销占比升高。长上下文请求的吞吐对 page 尺寸敏感度高于短请求：序列越长，gather 次数线性增长。标定时应把 page 尺寸与 KV 头维度、dtype 字节数对齐到 FlashAttention 的 tile 边界，使单 page 至少覆盖一个 IO tile；否则会出现“显存利用率提升 20–40%，但长上下文吞吐反而低于连续分配”的反常结果。这是一个纯系统代价问题，与量化方案无关。</p>\n<p>第三个边界是统一显存池的水位阈值。配额关系为</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>阈值设得过紧，KV page 换出与专家降级会互相触发：KV 被换出释放的空间被冷专家预取占用，水位再次越限又触发 KV 换出，形成换入换出震荡，拷贝开销把利用率收益抵消。判据是看单位时间内换出/换入次数与池水位的相关性，若二者同向波动即为震荡。可行做法是给专家侧与 KV 侧各设独立软阈值并加滞回区间，只在跨区间时动作，同时把专家降级放在 KV 换出之前——因为专家拷贝可预取、KV 换出不可预取。下表给出三类失效的观测点与代价归属。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测点</th><th>代价归属</th></tr></thead><tbody><tr><td>路由突变偏向冷专家</td><td>换出专家集合的访问增量</td><td>TPOT 尖峰，decode 关键路径</td></tr><tr><td>page 尺寸小于 IO tile</td><td>gather 次数/有效载荷比</td><td>长上下文吞吐下降</td></tr><tr><td>水位阈值无滞回</td><td>换出次数与水位相关性</td><td>拷贝开销抵消利用率收益</td></tr></tbody></table>\n<h3 id=\"alg-paged-kv-moe-sec-33\">三十三 · 先把“谁先崩”排成一张序</h3>\n<p>规模上去以后，这套统一显存池不会均匀地变慢，它按固定的先后顺序崩。第一崩的是<strong>尾延迟</strong>，不是平均吞吐；第二崩的是<strong>host-device 带宽</strong>，不是 HBM 容量；第三崩的才是 HBM 容量本身。原因在于：容量是静态约束，可以用配额公式提前算清；而尾延迟由路由分布的瞬时突变决定，无法用均值预测。把这三者的崩溃顺序排清楚，容量规划才有意义——否则你会把预算全砸在加 HBM 上，而真正的瓶颈是那条 PCIe 上的冷专家预取。</p>\n<p>判断依据是配额关系本身：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>这个不等式左侧是硬约束，右侧两项此消彼长。当并发上升，$N_{\\text{page}}$ 单调增长，$\\mathcal{H}$ 必须收缩；收缩意味着更多专家被判定为冷、移出 HBM。于是容量问题被转译成<strong>命中率问题</strong>：</p>\n<div class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>命中率的分母是路由总令牌数，分子只统计落在常驻集合内的令牌。容量压力越大，$\\mathcal{H}$ 越小，命中率越低；而命中率每掉一个点，就有相应比例的令牌要在 decode 关键路径上等一次 host-device 拷贝。这就是“容量→命中率→尾延迟”的传导链，也是本部分所有代价分析的骨架。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-34\">三十四 · 显存：配额是零和的，碎片消除只买回一次</h3>\n<p>统一显存池的第一个代价是配额零和。KV page 与热专家权重共享同一块 HBM，任何一方扩容都以另一方收缩为代价。分页分配消除的是<strong>外部碎片</strong>——连续分配下，长上下文请求要一整段连续空间，高并发时这些空洞拼不起来，请求被拒绝或排队；改成固定大小 page 后，page 从池中零散取用，长上下文与高并发可以在同一池内共存。材料给出的显存利用率提升 20–40% 就来自这部分回收。</p>\n<p>但这 20–40% 是一次性红利，不是可持续的扩容手段。利用率提上去之后，池水位会更快逼近阈值，触发更频繁的换出决策。真正的显存代价在于<strong>page table 本身的元数据</strong>：每个请求要为最大生成长度预留 page 数，page table 条目随 $N_{\\text{page}}$ 线性增长，这部分开销不随 page 变大而消失，只随 page 变小而膨胀。工程判断是：page 尺寸标定直接决定显存账本的形状——page 大，元数据省、IO 效率高，但内部碎片回升；page 小，外部碎片几乎为零，可 page table 间接寻址的地址计算与小粒度 IO 会吃掉收益。</p>\n<p>具体例子：一个长上下文请求按最大生成长度预留 page，若 page 取得偏小，它的 page table 条目数会显著增多，attention kernel 每次 gather 要做的间接寻址次数同比上升。此时即便 HBM 水位看起来健康，长上下文请求的吞吐也可能低于连续分配方案——碎片省下来的空间，被寻址开销还了回去。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-35\">三十五 · 带宽：两条互相踩踏的通道</h3>\n<p>带宽代价分两条通道，且它们会互相踩踏。第一条是 <strong>HBM 带宽</strong>：attention kernel 按 page table gather KV，FlashAttention 以 page 为粒度做 IO，gather 的随机性使有效带宽低于顺序读；page 越小，单次 IO 的有效载荷越小，带宽利用率越差。第二条是 <strong>host-device 带宽</strong>：冷专家换入换出走的是这条通道，它与 HBM 通道物理独立，但共享同一个 decode 时间窗。</p>\n<p>踩踏发生在时间维度上。decode 是逐 token 推进的，每个 token 的时延预算被 TPOT SLO 卡死。当某个 token 的路由突然偏向被换出的冷专家，系统必须在 token 的关键路径上串行插入一次 host-device 拷贝——注意是<strong>串行插入</strong>，不是并行掩盖。这次拷贝的时延直接叠加到该 token 的 TPOT 上，形成尖峰。更糟的是，拷贝完成后热度表异步更新，该专家被提升为热、挤占 KV page 配额，下一批请求又要换出别的 page，形成第二轮抖动。</p>\n<p>量化这个代价的思路是：设单 token 的 TPOT 预算为 $T_{\\text{TPOT}}$，冷专家拷贝耗时为 $t_{\\text{copy}}$，则尖峰 token 的时延约为 $T_{\\text{TPOT}} + t_{\\text{copy}}$，只要 $t_{\\text{copy}}$ 超过预算余量，SLO 即被击穿。这里的工程含义不是“拷贝慢”，而是<strong>拷贝没有隐藏窗口</strong>：decode 阶段每 token 的计算量小，没有足够的并行工作去掩盖一次 host-device 传输，这与预填阶段可以靠大块计算掩盖 IO 完全不同。</p>\n<p>具体例子：路由分布突变使请求集中到刚被换出的冷专家，多个请求在同一 decode 步同时触发预取，host-device 通道排队，单 token 时延尖峰被放大而非摊薄。这是失败模式里最锋利的一条。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-36\">三十六 · 通信：page 粒度改变了集合通信的形状</h3>\n<p>分页 KV 与专家分层驻留对通信的影响是间接但确定的。在专家并行下，All-to-All 的调度以令牌为单位；而 KV page 的非连续分配意味着 attention 侧的 KV 读取不再有规整的地址模式，跨设备的 KV 传输（若存在）也要按 page 粒度打包，单次传输的有效载荷受 page 尺寸约束。page 越小，通信消息数越多、单消息越小，固定开销占比越高。</p>\n<p>更关键的是<strong>换出决策与集合通信的耦合</strong>。统一显存池水位超阈值时触发 KV page 换出或专家权重降级，这个决策是全局的、异步的；而 All-to-All 是同步的、按批推进的。两者节奏不一致时，一次换出可能恰好落在某个 All-to-All 的关键窗口内，把通信延迟叠进 decode 步。工程上的处理是把换出决策绑定到批边界而非 token 边界，让换出与通信错峰——这属于调度策略，不属于 kernel 优化。</p>\n<p>代价的定性表述：page 尺寸标定过小，不仅拖累 attention 的 IO 效率，还会推高跨设备 KV 传输的消息数与固定开销，长上下文请求的吞吐被双向挤压。因此 page 尺寸的选择必须同时满足 attention 局部性与通信打包效率两个约束，不能只按碎片率优化。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-37\">三十七 · 功耗：常驻集合的静态底噪</h3>\n<p>功耗代价容易被忽略，但它在容量规划里占一席。热专家常驻 HBM 意味着这部分权重长期占据显存并保持可读状态，构成一份<strong>静态功耗底噪</strong>；KV page 的读写是动态的，随并发与上下文长度波动。统一显存池把两者放在同一配额下，等于把静态底噪与动态负载绑在一个预算里：并发低时，热专家集合可以放大，底噪上升但换出减少；并发高时，热专家收缩，底噪下降但拷贝功耗上升。</p>\n<p>这里没有可引用的具体瓦数，只能给出结构判断：功耗的最优点不在两端，而在<strong>换出频率与常驻规模平衡</strong>的位置。频繁换出会把功耗从静态显存保持转移到 host-device 传输上，而后者的能效比通常更差——单位有效载荷的传输功耗高于同载荷的 HBM 读。因此“把冷专家全赶到 NVMe”不是省电策略，而是把功耗从 HBM 挪到 IO 通道，总量未必下降。</p>\n<p>具体例子：三级存储（HBM + host + NVMe）下，NVMe 层的专家预取延迟远高于 host 内存，若热度表更新滞后，请求会连续命中 NVMe 层，形成“低功耗但高延迟”的配置——省了显存与静态功耗，却在尾延迟上付出更大代价。这正是配额阈值设置不当会引发的震荡来源之一。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-38\">三十八 · 尾延迟：三条失败模式的共同出口</h3>\n<p>把前面几条收束到尾延迟，可以看到三条失败模式其实共用一个出口：<strong>decode 关键路径上出现了不可掩盖的串行等待</strong>。</p>\n<ul>\n<li><strong>路由突变型</strong>：请求集中到被换出的冷专家，host-device 拷贝串行插入 decode，单 token 时延尖峰击穿 TPOT SLO。这条的触发条件是热度表滞后于路由分布，异步更新给了它窗口。</li>\n<li><strong>page 过小型</strong>：attention kernel 地址计算与 IO 效率下降，page table 间接寻址开销占比升高，长上下文吞吐反低于连续分配。这条的触发条件是 page 尺寸按碎片率而非按 IO 局部性标定。</li>\n<li><strong>阈值抖动型</strong>：池水位阈值设置不当，KV page 换出与专家权重降级频繁互相触发，形成换入换出震荡，20–40% 的利用率提升被拷贝开销抵消。这条的触发条件是换出决策缺少滞回（hysteresis），阈值单点触发。</li>\n</ul>\n<p>三条模式的共同工程判断是：尾延迟不是由平均命中率决定的，而是由<strong>命中率的最低瞬时值</strong>决定的。材料给出的 decode 阶段热专家命中率通常 &gt;90% 是均值口径，均值掩盖不了突变窗口内的塌陷。容量规划若按均值命中率配 SLO，就会在突变时被击穿。</p>\n<p>对应的机制层应对是把换出决策做成带滞回的双阈值：水位超过高阈值才换出，低于低阈值才回迁，中间区间保持不动；同时把热度表更新与批边界对齐，避免在 decode 步中途改变常驻集合。这两条都不增加 HBM，只改变决策时序，却能直接压掉阈值抖动型失败模式。规模上去以后先崩的是尾延迟，而尾延迟的修复点不在容量，在决策时序——这是本部分落到具体机制上的工程结论。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-39\">三十九 · 规模上去以后，先崩的是配额而不是容量</h3>\n<p>把权重与 KV 放进同一个池，容量本身不是最先出问题的地方，最先出问题的是配额的动态平衡。约束可写成 $$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$，其中 $\\mathcal{H}$ 是常驻热专家集合。并发上升时 $N_{\\text{page}}$ 单调增长，$\\mathcal{H}$ 只能被动收缩；一旦收缩触到路由实际需要的专家集合，冷专家的 host-device 拷贝就串行插入 decode 关键路径。这条路径上的单 token 时延不是平滑上升，而是尖峰——TPOT SLO 被击穿往往发生在池水位刚过阈值、换出与预取开始互相追赶的那一小段区间，而不是在显存真正耗尽时。规模越大，$\\mathcal{H}$ 的收缩余量越薄，尖峰出现的频率越高。</p>\n<p>第二个先崩的是 page 尺寸标定。page table 间接寻址让 attention kernel 的地址计算从一次线性偏移变成多次查表加 gather，FlashAttention 以 page 为粒度做 IO 时，小 page 意味着每次 IO 的有效载荷变薄、描述符开销占比升高。page 过小时长上下文请求的吞吐反而低于连续分配方案——碎片省下来的显存，被地址计算与 IO 效率吃掉。这与显存利用率提升 20–40% 并不矛盾：那 20–40% 是容量账，page 太小则是带宽账与指令账，两者不在同一个维度上结算。</p>\n<p>第三个失效条件是阈值抖动。统一显存池的水位阈值若标定不当，KV page 换出与专家权重降级会互相触发：KV 换出腾出的空间被预取的冷专家占走，冷专家占位又迫使下一批 KV page 换出，形成换入换出震荡。此时 host-device 拷贝带宽成为实际瓶颈，显存利用率的提升被拷贝开销抵消，系统吞吐不升反降。判断是否进入震荡，看的是单位时间内换出 page 数与换入专家字节数是否同向增长，而不是看池水位本身。</p>\n<p>通信与功耗的代价随规模放大得更隐蔽。专家分层驻留把冷专家放到 host 内存与 NVMe，跨 NUMA 与 PCIe 的拷贝在单机内尚可掩盖，一旦并行拓扑跨节点，被换出的专家就可能落在远端，拷贝路径叠加了网络跳数，尾延迟的方差被进一步拉大。功耗侧则是另一笔账：常驻热专家让 HBM 的静态占用居高不下，而换入换出带来的 host 内存与 NVMe 访问把功耗从 HBM 侧转移到 IO 侧，整机功耗曲线变得更平但更难预测。工程判断很直接：当 decode 阶段热专家命中率仍能维持在 >90% 时，这套方案是净收益；一旦路由分布漂移使命中率下滑，先动的是 page 尺寸与水位阈值这两个标定参数，而不是继续加大卸载深度。</p>\n<h3 id=\"alg-paged-kv-moe-sec-40\">四十 · 精度问题：page gather 与权重降级两处数值断点</h3>\n<p>在这套统一显存池方案里，精度事故几乎不来自量化本身，而来自“数据被搬动”这件事。第一处断点在 attention 侧：KV 不再连续，kernel 必须按 page table 做 gather，再以 page 为粒度喂给 FlashAttention 做 IO。page 边界把一条 KV 序列切成若干段，若实现里对每段单独做 softmax 归一化再拼接，就会在段与段之间引入舍入差异；正确做法是保持 online softmax 的 running max 与 running sum 跨 page 连续传递，使分页只是寻址方式的变化，不改变归约顺序的数学等价性。第二处断点在专家侧：冷专家换出到 host 再预取回来，若 host 侧存放的是与 HBM 不同精度的副本（例如为省带宽压成更低比特），换入后与热专家的数值路径就不一致，同一 token 在不同 batch 里走到同一专家却得到不同量级的输出，表现为输出漂移而非报错。</p>\n<p>诊断这两类问题的手段是分层比对：固定一组 prompt，强制路由到指定专家集合，分别在“全热常驻”和“含冷专家换入”两种配置下跑同一 batch，逐层比较激活的 max-abs 偏差；attention 侧则构造跨 page 边界的长上下文，比较分页 kernel 与连续 kernel 的 logits 差异。判据不是“有没有差异”，而是差异是否随 page 数增长而累积——若随 page 数线性放大，说明 online softmax 状态没有跨 page 正确传递。</p>\n<div class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>这个命中率既是性能指标也是精度指标：命中率跌到阈值以下，意味着更多 token 走了“换入—计算—换出”的路径，数值路径切换频次上升。系统代价上，精度校验本身要占用带宽——逐层比对需要把激活搬回 host，在大 batch 下这项开销会挤占 KV page 的换出带宽，因此校验必须抽样而非全量。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-41\">四十一 · OOM：配额不等式被击穿的三条路径</h3>\n<p>OOM 在本方案里不是“显存不够”，而是配额关系被瞬时打破。核心约束是</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>三条击穿路径：其一，请求进入时按最大生成长度预留 page 数，若并发突增而预留策略不做上限截断，$N_{\\text{page}}$ 会在预填充阶段就把池吃满，此时热专家集合 $\\mathcal{H}$ 尚未收缩，两边同时膨胀；其二，热度表异步更新存在滞后，$\\mathcal{H}$ 里挂着已经变冷的专家，实际可用给 KV 的空间小于账面值；其三，换出与降级是异步的，触发阈值到实际释放之间有窗口期，新请求在这个窗口内继续分配 page，形成“账面已释放、物理未释放”的假余量。</p>\n<p>诊断要点是把 OOM 分成“分配失败”和“预留失败”两类分别计数。分配失败说明池水位真的到顶；预留失败说明预留策略过于激进——按最大生成长度预留是保守估计，但长上下文请求的最大长度分布是重尾的，少数超长请求会把预留额度拉高，挤掉大量短请求的并发。工程判断是给预留加一个按分位数截断的上限，超出部分转为按需分配并接受可能的抢占。代价上，截断预留会提高长请求被抢占的概率，表现为这部分请求的 TTFT 抖动，但换来的是整体并发容量不被少数请求绑架。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-42\">四十二 · 批抖动与路由不均：热度表的滞后代价</h3>\n<p>批抖动指连续批处理中 batch 组成在相邻迭代间剧烈变化，导致每步的专家激活集合不稳定。根因是热度表异步更新与路由分布的实际变化之间存在时间差：路由在 token 级瞬时决定，热度表在请求级统计频次，两者时间尺度不一致。当一批请求的路由集中到某个刚被判定为冷、正在换出的专家上，decode 关键路径上就串行插入 host-device 拷贝，单 token 时延出现尖峰并击穿 TPOT SLO。这就是本方案最典型的失败模式。</p>\n<p>路由不均的诊断不能只看全局命中率，要看 per-expert 的激活计数分布与换出状态的交叉表：把专家按“当前是否常驻”和“本窗口激活次数”两个维度分桶，若“已换出且激活次数进入前 K”的桶非空且规模上升，说明热度判定滞后于路由漂移。监控上应采集每层每专家的激活直方图，与热度表快照做时间对齐比对。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>直接观测</th><th>根因定位</th><th>处置方向</th></tr></thead><tbody><tr><td>TPOT 尖刺</td><td>单 token 时延分布长尾</td><td>冷专家换入串行插入 decode</td><td>预取提前量、换出滞后</td></tr><tr><td>批抖动</td><td>相邻迭代 batch 专家集合差异大</td><td>热度表更新滞后于路由</td><td>缩短统计窗口、加迟滞</td></tr><tr><td>路由不均</td><td>per-expert 激活直方图偏斜</td><td>容量因子与实际分布不匹配</td><td>调整常驻集合 $\\mathcal{H}$</td></tr></tbody></table>\n<p>系统代价上，缓解尖刺的常规手段是给换入加预取提前量，即在路由概率尚未确定前就按历史分布预取候选专家，代价是预取可能落空，浪费 host-device 带宽并占用本可给 KV page 的 HBM 空间；另一种是给换出加迟滞，让刚变冷的专家多驻留若干窗口，代价是常驻集合偏大，压缩 KV 配额。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-43\">四十三 · 尾延迟尖刺：page 尺寸与换入换出的耦合</h3>\n<p>尾延迟有两个独立来源，容易被混为一谈。来源一是专家换入换出，如上节所述，是 host-device 拷贝串行插入关键路径。来源二是 page 尺寸标定过小：page table 间接寻址使 attention kernel 地址计算更复杂，小 page 时 IO 效率下降，page table 开销占比升高，长上下文请求吞吐反而低于连续分配方案。两者叠加时，长上下文请求既承受更多 page 寻址开销，又更容易触发专家换出，尾延迟被双重放大。</p>\n<p>诊断要把尾延迟按请求类型切开：长上下文请求的 P99 与短请求的 P99 分开统计，若长请求尾延迟显著更差且与 page 数正相关，指向 page 尺寸问题；若尾延迟尖刺与专家换出事件在时间上对齐，指向换入路径。监控上应记录每次换出/换入事件的起止时间戳，与请求级时延做关联分析，而不是只看聚合指标。</p>\n<div class=\"formula\">$$\\text{HBM}_{\\text{used}}=\\underbrace{N_{\\text{page}}\\cdot 2\\,L\\,H\\,d}_{\\text{KV}}+\\underbrace{\\sum_{e\\in\\text{hot}}|W_e|}_{\\text{resident experts}}$$</div>\n<p>这个式子说明 page 尺寸的选择是双向的：page 变大，$N_{\\text{page}}$ 变小、page table 变短、地址计算简化，但单 page 字节 $S_{\\text{page}}$ 变大，内部分片浪费上升，且换出粒度变粗，KV 换出的带宽峰值更高。工程判断是按上下文长度分布选 page 尺寸，让绝大多数请求的 KV 占用是 page 的整数倍附近，而不是一味求小。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-44\">四十四 · 监控体系：把水位、命中率、换出事件放在同一时间轴</h3>\n<p>本方案的监控不能沿用“GPU 利用率 + 显存占用”的老三样，因为统一显存池里权重与 KV 共享同一块 HBM，聚合显存占用无法区分是谁在挤谁。必须采集四类信号并对齐时间轴：池水位（区分 KV page 占用与常驻专家占用两部分）、专家命中率（按层按专家）、换出/换入事件流（含字节数与耗时）、以及请求级 TTFT/TPOT 分布。</p>\n<ul>\n<li>水位信号要拆成“账面配额”与“物理占用”两条线，两者差值就是异步释放的窗口期，窗口期持续扩大是 OOM 的前兆。</li>\n<li>命中率信号要按窗口滑动统计，并与路由直方图做交叉，单看命中率会掩盖局部专家的频繁换入。</li>\n<li>换出事件流要记录触发原因（水位超阈值、热度降级、还是抢占），不同原因的处置策略不同。</li>\n<li>请求级指标要按上下文长度分桶，否则长请求的尾延迟会被短请求的均值稀释。</li>\n</ul>\n<p>系统代价上，这些信号本身产生可观的开销：per-expert 激活计数需要在 kernel 内做原子累加或后置归约，高频采样会占用 SM 周期；事件流的时间戳采集若同步写入会引入锁竞争。可行做法是分层采样——高频轻量计数在 device 侧聚合后周期性搬回，重量级事件流只在触发阈值时开启详细记录。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-45\">四十五 · 回滚：把配额与热度策略做成可切换的参数面</h3>\n<p>回滚的对象不是代码版本，而是运行时策略。三类失败模式对应三组可回滚参数：预留策略（最大生成长度预留 vs 分位数截断）、热度策略（统计窗口长度、换出迟滞窗口、常驻集合上限）、page 策略（page 尺寸、换出粒度）。回滚的前提是这些参数在运行时可变且变更可审计。</p>\n<p>具体机制上，回滚应遵循“先冻结再切换”的顺序：检测到 TPOT 尾延迟击穿 SLO 时，第一步冻结热度表的异步更新，阻止常驻集合继续收缩，避免换出事件继续叠加；第二步把换出迟滞窗口调大，让已换出的专家在下一窗口优先被预取回；第三步若仍不收敛，把 page 换出阈值上调，优先保 KV 而接受专家降级——这与正常水位策略的方向相反，属于应急降级。每一步都要记录切换前后的命中率与尾延迟，用于判断是否需要继续回滚。</p>\n<p>工程判断在于：回滚的粒度必须小于故障扩散的粒度。若换出与降级互相触发形成震荡，单参数调整往往无效，需要一次性把热度更新与水位阈值同时切到保守档，再逐步放开。代价是保守档下常驻集合偏大、KV 配额偏小，并发容量下降，表现为吞吐回退——这是用吞吐换稳定性的显式交易，必须在容量规划里预留这段回退空间，而不是等故障发生时才临时压缩并发。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-46\">四十六 · 失效条件、诊断信号与回滚边界</h3>\n<p>这套方案的收益全部建立在两个前提上：专家路由分布相对稳定，且 page 尺寸与 attention kernel 的寻址开销匹配。一旦前提破裂，失败不是渐变而是阶跃式的。最典型的失效路径是路由突变：某类请求涌入使流量集中到已被换出到 host 的冷专家，预取来不及覆盖，host-device 拷贝被串行插入 decode 关键路径，单 token 时延出现尖峰并直接击穿 TPOT SLO。诊断信号应盯住三个量——热专家命中率相对基线的偏移、单位时间 host-to-device 拷贝字节数与拷贝次数、以及 decode 步内拷贝等待占该步墙钟时间的比例。命中率跌破 90% 这条经验线时，拷贝占比通常已开始主导尾延迟；此时把命中率与 TPOT 分位数画在同一时间轴上，能直接看出尖峰是否由换入触发，而不是归咎于批调度。</p>\n<p>第二个失效面在 page 尺寸标定。page 过小，page table 间接寻址在 attention kernel 中的地址计算占比升高，FlashAttention 以 page 为粒度的 IO 效率下降，长上下文请求吞吐反而低于连续分配方案；page 过大则内部碎片回升，长上下文与高并发共存的初衷被削弱。可用的判据是把单请求的有效载荷率写成</p>\n<div class=\"formula\">$$\\eta=\\frac{L_{\\text{ctx}}\\cdot S_{\\text{token}}}{N_{\\text{page}}\\cdot S_{\\text{page}}},\\qquad \\text{overhead}\\propto \\frac{N_{\\text{page}}}{L_{\\text{ctx}}}$$</div>\n<p>其中分子是真实 KV 字节、分母是实际占用的 page 字节。$\\eta$ 下滑说明碎片在吃收益，$N_{\\text{page}}/L_{\\text{ctx}}$ 上升说明寻址开销在吃吞吐，两者应同时监控而非只看显存占用率。</p>\n<p>第三个失效面是配额震荡。统一显存池的水位阈值设置不当时，KV page 换出与专家权重降级会互相触发：KV 换出腾出的空间被冷专家预取占用，水位再次越线又触发新一轮降级，形成换入换出振荡，20–40% 的利用率提升被拷贝开销抵消。工程上应给两类动作加不对称的滞回区间与最小驻留时间，并把“单位时间换出次数”作为一级告警指标而非派生指标。回滚路径按代价从低到高排列：先把水位阈值上调、暂停专家降级只做 KV 换出；再把冷专家集合整体钉回 HBM（放弃分层收益换确定性延迟）；最后退回连续分配 KV 并关闭统一池，此时长上下文与高并发不再共存，需同步下调并发准入。回滚判据应绑定 SLO 而非利用率——利用率再高，TPOT 尾分位数越线就必须退。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>一级信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>路由偏向冷专家</td><td>命中率跌破 90%、decode 步拷贝等待占比上升</td><td>扩大热专家集合，暂停降级</td></tr><tr><td>page 过小</td><td>$\\eta$ 正常但 $N_{\\text{page}}/L_{\\text{ctx}}$ 升高、长上下文吞吐下降</td><td>放大 page 尺寸，重标定</td></tr><tr><td>配额震荡</td><td>单位时间换出次数抖动</td><td>上调水位阈值，加滞回</td></tr></tbody></table>\n<h3 id=\"alg-paged-kv-moe-sec-47\">四十七 · 对照维度：把“争抢同一块 HBM”拆成三个可比较的轴</h3>\n<p>与相邻算法对照时，不要停留在“谁更省显存”这种笼统判断上。本算法与同族方案的分野可以拆成三个正交轴：KV 的分配方式（连续 vs. page 化）、专家权重的驻留策略（全常驻 vs. 纯卸载 vs. 分层热度驻留）、以及配额决策的主体（各自独立管理 vs. 统一池按 SLO 动态分配）。任何一个具体系统都落在这三个轴的某个坐标上，选型就是选坐标。轴一决定外部碎片与长上下文可共存性；轴二决定冷专家换入换出的拷贝频率；轴三决定在负载漂移时谁先被牺牲。把这三轴画成表，比记一堆方案名有用。</p>\n<p>对照的基准是两条：连续分配 KV cache（传统 PagedAttention 之前的做法，或按最大长度整块预留）与纯专家卸载方案（权重与 KV 各自独立管理，专家换出策略不看 KV 水位）。本算法的差异点恰好是“page table 间接寻址”与“统一显存池按 SLO 分配配额”两件事的组合，缺一件就退化回基准之一。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-48\">四十八 · 决策表：按负载形态选族内算法</h3>\n<p>下表把族内可选形态与触发条件对齐。判断依据是三个可观测量：并发请求数相对 HBM 容量的比值、上下文长度分布的尾部、以及路由分布的漂移速度（可用热专家集合的日均变动率定性估计）。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>形态</th><th>KV 分配</th><th>专家驻留</th><th>配额决策</th><th>适用条件</th><th>主要代价</th></tr>\n</thead>\n<tbody>\n<tr><td>连续分配 + 专家全常驻</td><td>整块预留</td><td>全部 HBM</td><td>无</td><td>并发低、上下文短、专家总数小到能全塞进 HBM</td><td>长上下文请求直接挤掉并发，外部碎片随请求长度方差放大</td></tr>\n<tr><td>page 化 KV + 专家全常驻</td><td>固定 page 非连续</td><td>全部 HBM</td><td>仅 KV 侧</td><td>专家权重占比可控、KV 是主要增长项</td><td>专家常驻吃掉本可给 KV 的配额，page 化收益被压缩</td></tr>\n<tr><td>连续 KV + 纯专家卸载</td><td>整块预留</td><td>冷专家在 host/NVMe</td><td>仅专家侧</td><td>专家数极大、KV 并发压力中等</td><td>长上下文仍受碎片限制；卸载与 KV 扩容互不知情，易互相踩踏</td></tr>\n<tr><td>page 化 KV + 分层热度驻留 + 统一池</td><td>固定 page 非连续</td><td>热常驻、冷分层</td><td>统一池按 SLO</td><td>长上下文与高并发混合、专家集合大且热度集中</td><td>page table 寻址开销；冷专家换入换出造成时延尖峰</td></tr>\n</tbody>\n</table>\n<p>读表方式：前两行是“只解决一半”的形态，第三行是另一半，第四行才是本算法。若你的负载里上下文长度方差小、并发上限可预估，第一行反而最省心——page 化的寻址开销换不来碎片收益。若专家集合大到全常驻不可能、但上下文普遍短，第三行足够，不必引入统一池的复杂度。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-49\">四十九 · 适用条件的量化判据</h3>\n<p>把“要不要上统一池”写成不等式。设热专家集合为 $\\mathcal{H}$，其权重总量为 $\\sum_{e\\in\\mathcal{H}}W_e$，KV 侧按最大生成长度预留的 page 总量为 $N_{\\text{page}}\\cdot S_{\\text{page}}$，则统一池可行的必要条件是两者之和逼近但不超过 HBM：</p>\n<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>\n<p>若左侧余量长期大于右侧需求的三成以上，说明配额压力不足，统一池的动态调整几乎不会触发，收益趋近于零，此时选第二行形态即可。反之若右侧在峰值并发下显著超过左侧，统一池必须频繁换出，换入换出开销会吃掉 page 化带来的利用率提升——这正是失败模式里“水位阈值抖动”的成因。判据的第二个量是热度集中度：</p>\n<div class=\"formula\">$$\\text{hit rate}=\\frac{\\sum_e \\mathbb{1}[e\\in\\text{hot}]\\,n_e}{\\sum_e n_e}$$</div>\n<p>材料给出的定性锚点是 decode 阶段热专家命中率通常 &gt;90%。命中率越高，冷专家换入换出越少，分层驻留越划算；若命中率长期低于这个量级，说明路由分布分散，热集合本身就不稳定，分层策略退化为频繁预取，此时应回到“专家全常驻 + page 化 KV”并接受专家占用，或改用专家并行把权重摊到多卡。</p>\n<p>具体例子：一个长上下文对话服务，峰值并发下 KV 需求随生成长度线性涨，而专家权重固定占用一大块。若不做 page 化，长请求进来时只能整块预留，把并发挤下去；若做 page 化但不统一池，KV 扩容时不知道专家侧还有多少可让出的空间，只能等 OOM 或人工调参。统一池的价值就在这个“知道对方还有多少余量”的信息上，而不是 page 化本身。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-50\">五十 · 与专家并行、分离式部署的边界</h3>\n<p>族内还有一个常被混为一谈的邻居：专家并行（把专家分散到多卡，靠 All-to-All 调度）。它与本算法不是替代关系而是互补关系——专家并行降低单卡权重占用，本算法降低单卡 KV 与权重的争抢。选型判据是：当单卡 HBM 连热专家集合都放不下时，先上专家并行把 $\\sum_{e\\in\\mathcal{H}}W_e$ 除以卡数，再谈统一池；当单卡放得下热集合、瓶颈在 KV 随并发线性增长时，本算法是主手段。两者叠加时要注意 All-to-All 的通信延迟会与本算法的冷专家预取拷贝竞争同一条 host-device 与卡间链路，配额决策需把通信预算也计入水位。</p>\n<p>与预填/解码分离部署的边界同理：分离部署把预填的算力压力与解码的显存压力拆到不同实例，天然缓解争抢；若已分离，本算法的统一池主要服务于解码实例内部的 KV 与热专家共存，预填侧的长上下文 page 化收益则体现在预填实例的批调度上。判断顺序应是：先看能否靠分离部署把两类压力物理隔离，隔离不了再上统一池；隔离得了，统一池的复杂度就是多余的。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-51\">五十一 · 选型后的参数落点与代价核算</h3>\n<p>选定第四行形态后，两个参数直接决定成败：page 尺寸与水位阈值。page 过小则 attention kernel 地址计算与 IO 效率下降，page table 间接寻址开销占比升高，长上下文吞吐反而可能低于连续分配——这是材料明确指出的失败模式，因此 page 尺寸的下界应由“单次 IO 的有效字节数”反推，而不是由碎片率单独优化。水位阈值则要留出迟滞带：换出与降级若在同一阈值上反复触发，KV page 换出与专家权重降级会互相触发形成震荡，利用率提升被拷贝开销抵消。工程上给换出与回收设两个不同阈值（高水位触发换出、低水位才允许回收），并让专家热度表异步更新，避免热度抖动直接传导到换入换出决策。</p>\n<p>代价核算按三项计：一是 page table 寻址带来的 attention kernel 额外地址计算，随 page 数线性增长；二是冷专家 host-device 拷贝，其频率正比于 $1-\\text{hit rate}$，且串行插入 decode 关键路径时直接体现为 TPOT 尖峰；三是统一池水位管理的调度开销，量级小但抖动时会放大前两项。收益侧是材料给出的显存利用率提升 20–40%，这个区间对应的是“碎片消除 + 冷专家移出”两项叠加，单做其中一项拿不到上限。选型时若你的负载只能吃到其中一项收益，就按单项估，不要拿区间上限做容量规划。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-52\">五十二 · 一个可执行的判断序列</h3>\n<p>把上面的判据压成一条判断链，供工程落地时逐条过：第一步，量上下文长度分布的尾部与并发上限，若尾部短且并发可预估，选连续分配 + 全常驻，结束。第二步，若专家集合大到全常驻挤占 KV，先评估专家并行能否把热集合摊到多卡；能摊则并行优先，本算法退为辅助。第三步，若单卡放得下热集合、KV 是增长主项，上 page 化 KV，此时先不引入统一池，观察碎片是否仍是瓶颈。第四步，若 page 化后 KV 扩容仍与专家常驻互相踩踏、且热专家命中率稳定在 &gt;90% 量级，才引入统一池与分层驻留，并按第五节的迟滞带设阈值。第五步，上线后监控冷专家拷贝在 decode 关键路径上的插入频率与 page table 开销占比，任一指标恶化即回退到上一形态。这条链的核心判断是：统一池的复杂度只在“两类压力都无法物理隔离、且热度集中度足够高”时才付得起。</p>\n\n<h3 id=\"alg-paged-kv-moe-sec-53\">五十三 · 同族算法怎么选：三条路线的边界与失效条件</h3>\n<p>把分页 KV 与分层专家驻留放进同族算法谱系里看，真正要回答的不是“谁更先进”，而是“在给定 SLO 与负载配方下，谁的失效条件不会先被触发”。同族方案至少有三条路线：连续分配的 KV cache（vLLM 早期块式连续、TensorRT-LLM 的静态显存规划）、纯专家卸载（只把冷专家放 CPU/NVMe，KV 仍连续分配）、以及本方案的分页 KV + 统一显存池 + 热度分层驻留。前两者的共同点是权重与 KV 各自独立管理，配额在启动时静态切分；本方案把二者放进同一池子，按水位与 SLO 动态调。选择的第一判据是负载是否“长上下文与高并发混合”——若请求长度方差小、并发稳定，静态切分的碎片损失有限，引入 page table 间接寻址反而是净负担；若长度方差大且并发随流量抖动，连续分配的外部碎片会让长请求挤掉短请求，此时分页的收益才成立。第二判据是专家路由是否稳定：热度表异步更新意味着系统对路由分布做了平滑假设，路由若在时间尺度上快速漂移，热专家集合的估计就会滞后。</p>\n<p>决策表按“失效条件优先”组织，而不是按功能列表罗列：</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>适用条件</th><th>先失效的场景</th><th>主要系统代价</th></tr></thead><tbody><tr><td>连续分配 KV + 专家常驻</td><td>请求长度集中、并发可预测、专家总数小</td><td>长上下文请求到达时无连续空间，外部碎片导致拒绝或排队</td><td>HBM 利用率低，长请求 TTFT 抬升</td></tr><tr><td>纯专家卸载</td><td>专家权重占比高、KV 并发中等</td><td>路由偏向冷专家时 host-device 拷贝串行插入 decode</td><td>单 token 时延尖峰，TPOT 抖动</td></tr><tr><td>分页 KV + 统一池 + 分层驻留</td><td>长上下文与高并发共存、路由分布缓变</td><td>page 过小或水位阈值抖动</td><td>page table 地址计算开销、换入换出震荡</td></tr></tbody></table>\n<p>本方案的边界可以用配额不等式直接读出：<div class=\"formula\">$$M_{\\text{HBM}} \\ge \\sum_{e \\in \\mathcal{H}} W_e + N_{\\text{page}} \\cdot S_{\\text{page}}$$</div>当热专家集合 $\\mathcal{H}$ 因路由突变而扩张，或按最大生成长度预留的 $N_{\\text{page}}$ 随并发上升，不等式右侧逼近 $M_{\\text{HBM}}$，水位阈值触发换出。此时若换出的是 KV page，长上下文请求的 page table gather 会跨更多非连续页，attention kernel 的地址计算与 IO 效率同时下降；若降级的是专家权重，冷专家换入的 host-device 拷贝就落在 decode 关键路径上。两种代价不对称：KV 换出影响的是吞吐与 TTFT，专家换入影响的是单 token 时延即 TPOT。因此阈值策略应按 SLO 的紧约束侧倾斜——TPOT 紧就把专家驻留优先级抬高，TTFT 紧就保 page 供给。</p>\n<p>page 尺寸是第二个边界参数。page 过小时 page table 条目变多，间接寻址在 attention kernel 内的占比升高，FlashAttention 以 page 为粒度的 IO 被切碎，长上下文吞吐可能反而低于连续分配方案；page 过大则内部碎片回升，抵消分页消除外部碎片的收益。工程判断是：page 尺寸应使单页 IO 接近存储事务的粒度下限，同时让 page table 常驻片上或 L2 可容纳。第三边界是热度统计的更新周期——异步更新越慢，热专家命中率越依赖路由平稳；材料给出的 decode 阶段命中率通常 >90% 与利用率提升 20–40% 都建立在这一平稳假设上，一旦路由分布突变使请求集中到被换出的冷专家，拷贝串行化会直接击穿 TPOT SLO。选型时若无法保证路由缓变，应退回纯专家卸载并把冷专家预取做成流水线，而不是依赖统一池的动态降级。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · MoE推理KV cache压缩</td></tr><tr><td>解决什么</td><td>MoE 服务中专家权重常驻显存占用巨大，KV cache 随并发线性增长，二者争抢同一块 HBM；连续分配的 KV 造…</td></tr><tr><td>一句话机制</td><td>把 KV cache 切为固定大小的 page 并按需分配，专家权重按热度分层驻留（热专家常驻 HBM、冷专家放 CP…</td></tr><tr><td>代价与失效</td><td>冷专家换入换出引入 host-device 拷贝，若路由突然偏向冷专家会造成单 token 时延尖峰；page table 间接寻址使 a…</td></tr><tr><td>后继</td><td>MoE 预填解码分离部署</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-paged-kv-moe · 共 8 个片段</p>\n";break;}}})();
